INSERT INTO public.landing_pages(tenant_id,path,title,summary,sections,kind,image,faq,status,city,district,neighborhood,service,local_context,logistics,evidence,reviewed_at) SELECT id,'/sektorler/endustriyel','Endüstriyel üretim','Üretim hattındaki özel aparat, montaj yardımcısı ve düşük adetli parça ihtiyaçlarını aynı teknik briefte toplayın. 3dyanımda: prototip & kurumsal üretim odağında değerlendirme.','[{"title":"Prototip & kurumsal üretim","body":"3dyanımda: İstanbul’da 3D baskı, 3D tarama ve 3D modelleme. Prototip & kurumsal üretim için proje bazlı üretim. Projenizde 3D baskı, 3D tarama ve 3D modelleme adımlarından hangilerinin gerekli olduğunu kullanım amacınızla birlikte belirleyin."},{"title":"Hattaki görevi tarif edin","body":"Parçanın hangi operasyonda kullanıldığını, operatörün nasıl tuttuğunu ve hangi yüzeylerin referans alındığını açıklayın. Çevrim sırasında oluşan yük, sıcaklık ve kimyasal temas bilgisi üretim kararının girdisidir. Mevcut çizim varsa kritik ölçüleri ayrı işaretleyin."},{"title":"Pilot parçadan onaylı revizyona","body":"İlk numuneyi gerçek montaj noktasında değerlendirecek kişiyi belirleyin. Uyum, erişim ve operatör kullanımı ayrı kontrol başlıkları olmalıdır. Numune üzerinde yapılan değişiklikleri çizim revizyonuna işleyin; seri talebi yalnızca onaylanan dosyaya bağlayın."},{"title":"Satın alma dosyası","body":"Talebe parça kodu, adet, malzeme beklentisi ve kabul ölçütlerini ekleyin. Birden fazla parçanın aynı siparişte değerlendirilmesi gerekiyorsa dosya adlarını adet tablosuyla eşleştirin. Tekrarlı siparişlerde önceki revizyon ve değişen koşulları belirtin."}]'::jsonb,'sector','/brand/industrial/fixture.webp','[{"q":"İlk değerlendirme için ne paylaşmalıyım?","a":"Parçanın hangi operasyonda kullanıldığını, operatörün nasıl tuttuğunu ve hangi yüzeylerin referans alındığını açıklayın. Çevrim sırasında oluşan yük, sıcaklık ve kimyasal temas bilgisi üretim kararının girdisidir. Mevcut çizim varsa kritik ölçüleri ayrı işaretleyin."},{"q":"Talebe nasıl başlayabilirim?","a":"3D Studio üzerinden dosyanızı, adet ve kullanım koşullarınızı paylaşabilirsiniz. Dosyanız yoksa fotoğraf, ölçü ve beklenen çıktıyla modelleme değerlendirmesi isteyin."}]'::jsonb,'published','','','','','','','',NULL FROM public.tenants WHERE slug='3dyanimda' ON CONFLICT(tenant_id,path) DO NOTHING;
INSERT INTO public.landing_pages(tenant_id,path,title,summary,sections,kind,image,faq,status,city,district,neighborhood,service,local_context,logistics,evidence,reviewed_at) SELECT id,'/sektorler/otomotiv','Otomotiv ve yedek parça','Trim, kapak, klips ve prototip parçalarında numuneden modele uzanan süreci kullanım koşullarıyla birlikte planlayın. 3dyanımda: prototip & kurumsal üretim odağında değerlendirme.','[{"title":"Prototip & kurumsal üretim","body":"3dyanımda: İstanbul’da 3D baskı, 3D tarama ve 3D modelleme. Prototip & kurumsal üretim için proje bazlı üretim. Projenizde 3D baskı, 3D tarama ve 3D modelleme adımlarından hangilerinin gerekli olduğunu kullanım amacınızla birlikte belirleyin."},{"title":"Montaj ilişkisini koruyun","body":"Tek başına kırık parçanın fotoğrafı her zaman yeterli değildir. Parçanın takıldığı bölgeyi, sağlam eşini ve bağlantı elemanlarını da gösterin. Geçme yönü ve esnemesi gereken bölgeler işaretlenirse modelleme kapsamı daha doğru belirlenir."},{"title":"Ortam koşullarını paylaşın","body":"İç mekân, güneş gören bölge veya motor çevresi farklı koşullar taşır. Sıcaklık, titreşim, kimyasal temas ve beklenen kullanım ömrünü anlatın. Görünüş numunesi ile işlevsel kullanım parçasını aynı kabul kriteriyle değerlendirmeyin."},{"title":"Doğrulama kapsamı","body":"Emniyet açısından kritik bir parçanın yeniden üretilmesi ayrıca mühendislik doğrulaması gerektirir. Talepte parçanın görevini açıkça belirtin. Prototipin montaja oturması, tek başına güvenli kullanım onayı anlamına gelmez."}]'::jsonb,'sector','/brand/industrial/fixture.webp','[{"q":"İlk değerlendirme için ne paylaşmalıyım?","a":"Tek başına kırık parçanın fotoğrafı her zaman yeterli değildir. Parçanın takıldığı bölgeyi, sağlam eşini ve bağlantı elemanlarını da gösterin. Geçme yönü ve esnemesi gereken bölgeler işaretlenirse modelleme kapsamı daha doğru belirlenir."},{"q":"Talebe nasıl başlayabilirim?","a":"3D Studio üzerinden dosyanızı, adet ve kullanım koşullarınızı paylaşabilirsiniz. Dosyanız yoksa fotoğraf, ölçü ve beklenen çıktıyla modelleme değerlendirmesi isteyin."}]'::jsonb,'published','','','','','','','',NULL FROM public.tenants WHERE slug='3dyanimda' ON CONFLICT(tenant_id,path) DO NOTHING;
INSERT INTO public.landing_pages(tenant_id,path,title,summary,sections,kind,image,faq,status,city,district,neighborhood,service,local_context,logistics,evidence,reviewed_at) SELECT id,'/sektorler/mimari-tasarim','Mimari ve tasarım','Kütle, cephe ve yerleşim maketlerinde ölçeği, gösterilecek detayları ve taşıma planını üretimden önce netleştirin. 3dyanımda: prototip & kurumsal üretim odağında değerlendirme.','[{"title":"Prototip & kurumsal üretim","body":"3dyanımda: İstanbul’da 3D baskı, 3D tarama ve 3D modelleme. Prototip & kurumsal üretim için proje bazlı üretim. Projenizde 3D baskı, 3D tarama ve 3D modelleme adımlarından hangilerinin gerekli olduğunu kullanım amacınızla birlikte belirleyin."},{"title":"Ölçekte okunabilirlik","body":"Kaynak modelin birimini, hedef maket ölçeğini ve bitmiş taban ölçüsünü paylaşın. Cephedeki çok küçük detayların fiziksel makette nasıl temsil edileceğini kararlaştırın. Peyzaj, kütle ve iç mekân farklı ayrıntı seviyelerinde ele alınabilir."},{"title":"Bölünebilir üretim","body":"Maketin sergileneceği alan ve taşınacağı kutu boyutu, parçalara ayırma kararını etkiler. Birleşim yerlerini görünür cephelerden uzaklaştırmak veya sökülebilir kütleler kullanmak tasarım aşamasında değerlendirilebilir. Aydınlatma ve kablo kanalları ayrıca belirtilmelidir."},{"title":"Sunum onayı","body":"Renk, yüzey, etiket ve taban beklentisini referanslarla anlatın. Önce dijital yerleşim, sonra kritik bir detayın numunesi üzerinden karar verin. Son teslimden önce parça listesi ve yerleşim şemasını birlikte kontrol edin."}]'::jsonb,'sector','/brand/industrial/fixture.webp','[{"q":"İlk değerlendirme için ne paylaşmalıyım?","a":"Kaynak modelin birimini, hedef maket ölçeğini ve bitmiş taban ölçüsünü paylaşın. Cephedeki çok küçük detayların fiziksel makette nasıl temsil edileceğini kararlaştırın. Peyzaj, kütle ve iç mekân farklı ayrıntı seviyelerinde ele alınabilir."},{"q":"Talebe nasıl başlayabilirim?","a":"3D Studio üzerinden dosyanızı, adet ve kullanım koşullarınızı paylaşabilirsiniz. Dosyanız yoksa fotoğraf, ölçü ve beklenen çıktıyla modelleme değerlendirmesi isteyin."}]'::jsonb,'published','','','','','','','',NULL FROM public.tenants WHERE slug='3dyanimda' ON CONFLICT(tenant_id,path) DO NOTHING;
INSERT INTO public.landing_pages(tenant_id,path,title,summary,sections,kind,image,faq,status,city,district,neighborhood,service,local_context,logistics,evidence,reviewed_at) SELECT id,'/sektorler/medikal','Medikal tasarım ve eğitim','Anlatım, eğitim ve tasarım değerlendirmesi için anatomik gösterim ve cihaz gövdesi prototiplerinin kapsamını belirleyin. 3dyanımda: prototip & kurumsal üretim odağında değerlendirme.','[{"title":"Prototip & kurumsal üretim","body":"3dyanımda: İstanbul’da 3D baskı, 3D tarama ve 3D modelleme. Prototip & kurumsal üretim için proje bazlı üretim. Projenizde 3D baskı, 3D tarama ve 3D modelleme adımlarından hangilerinin gerekli olduğunu kullanım amacınızla birlikte belirleyin."},{"title":"Kullanım amacını ayırın","body":"Eğitimde gösterim, cihazın form kontrolü ve klinik kullanım birbirinden farklı kapsamlar taşır. Talebinizin hangi amaçla kullanılacağını açıkça yazın. Bu sayfadaki prototipleme yaklaşımı klinik uygunluk, sterilizasyon veya hasta temasına ilişkin bir onay değildir."},{"title":"Veri paylaşımı","body":"Gerekli dosya formatını ve görüntüleme beklentisini teknik ekiple belirleyin. Kişisel bilgi içeren görüntü veya dosyaları paylaşmadan önce yetki ve anonimleştirme süreçlerinizi tamamlayın. Teklif aşamasında mümkünse kimlik bilgisi içermeyen geometriyle başlayın."},{"title":"Eğitim modelinin kabulü","body":"Gösterilecek yapıları, renk ayrımını, sökülebilir bölümleri ve kullanılacak ölçeği listeleyin. Modelin anlatım amacına uygunluğunu konu uzmanı değerlendirmelidir. Dijital onay ile fiziksel yüzey beklentisini ayrı adımlarda ele alın."}]'::jsonb,'sector','/brand/industrial/fixture.webp','[{"q":"İlk değerlendirme için ne paylaşmalıyım?","a":"Eğitimde gösterim, cihazın form kontrolü ve klinik kullanım birbirinden farklı kapsamlar taşır. Talebinizin hangi amaçla kullanılacağını açıkça yazın. Bu sayfadaki prototipleme yaklaşımı klinik uygunluk, sterilizasyon veya hasta temasına ilişkin bir onay değildir."},{"q":"Talebe nasıl başlayabilirim?","a":"3D Studio üzerinden dosyanızı, adet ve kullanım koşullarınızı paylaşabilirsiniz. Dosyanız yoksa fotoğraf, ölçü ve beklenen çıktıyla modelleme değerlendirmesi isteyin."}]'::jsonb,'published','','','','','','','',NULL FROM public.tenants WHERE slug='3dyanimda' ON CONFLICT(tenant_id,path) DO NOTHING;
INSERT INTO public.landing_pages(tenant_id,path,title,summary,sections,kind,image,faq,status,city,district,neighborhood,service,local_context,logistics,evidence,reviewed_at) SELECT id,'/sektorler/savunma-havacilik','Havacılık ve teknik Ar-Ge','Form kontrolü, ergonomi ve montaj gösterimi için kullanılan teknik prototipleri izlenebilir bir dosya akışıyla planlayın. 3dyanımda: prototip & kurumsal üretim odağında değerlendirme.','[{"title":"Prototip & kurumsal üretim","body":"3dyanımda: İstanbul’da 3D baskı, 3D tarama ve 3D modelleme. Prototip & kurumsal üretim için proje bazlı üretim. Projenizde 3D baskı, 3D tarama ve 3D modelleme adımlarından hangilerinin gerekli olduğunu kullanım amacınızla birlikte belirleyin."},{"title":"Kapsam ve veri sınırı","body":"Paylaşıma yetkili olduğunuz çizimleri ve kullanım amacı bilgisini talebe ekleyin. İlk değerlendirme için gerekli olmayan hassas proje detaylarını kapsam dışında tutun. Dosya erişimi, gizlilik ve revizyon sorumluları teklif öncesinde belirlenmelidir."},{"title":"Gösterim ve montaj prototipi","body":"Ergonomi maketi, bağlantı yerleşimi veya dış form numunesinde hangi kararın doğrulanacağını yazın. Görsel prototipin uçuşa elverişlilik veya işlevsel parça sertifikası sağlamadığını proje içinde açıkça ayırın. Kritik işlevler ayrı doğrulama planı gerektirir."},{"title":"İzlenebilir değerlendirme","body":"Dosya adı, parça kodu, revizyon, talep sahibi ve kabul kontrolünü ortak tabloda tutun. Fiziksel numune üzerindeki değişiklikleri dijital modele geri işleyin. Tekrar üretimde onaylı dosyanın aynı olduğundan emin olun."}]'::jsonb,'sector','/brand/industrial/fixture.webp','[{"q":"İlk değerlendirme için ne paylaşmalıyım?","a":"Paylaşıma yetkili olduğunuz çizimleri ve kullanım amacı bilgisini talebe ekleyin. İlk değerlendirme için gerekli olmayan hassas proje detaylarını kapsam dışında tutun. Dosya erişimi, gizlilik ve revizyon sorumluları teklif öncesinde belirlenmelidir."},{"q":"Talebe nasıl başlayabilirim?","a":"3D Studio üzerinden dosyanızı, adet ve kullanım koşullarınızı paylaşabilirsiniz. Dosyanız yoksa fotoğraf, ölçü ve beklenen çıktıyla modelleme değerlendirmesi isteyin."}]'::jsonb,'published','','','','','','','',NULL FROM public.tenants WHERE slug='3dyanimda' ON CONFLICT(tenant_id,path) DO NOTHING;
INSERT INTO public.landing_pages(tenant_id,path,title,summary,sections,kind,image,faq,status,city,district,neighborhood,service,local_context,logistics,evidence,reviewed_at) SELECT id,'/sektorler/egitim-arge','Eğitim ve Ar-Ge','Fikrinizi test edilebilir numunelere ayırın; bir sonraki tasarım kararını verecek prototipi üretin. 3dyanımda: prototip & kurumsal üretim odağında değerlendirme.','[{"title":"Prototip & kurumsal üretim","body":"3dyanımda: İstanbul’da 3D baskı, 3D tarama ve 3D modelleme. Prototip & kurumsal üretim için proje bazlı üretim. Projenizde 3D baskı, 3D tarama ve 3D modelleme adımlarından hangilerinin gerekli olduğunu kullanım amacınızla birlikte belirleyin."},{"title":"Deneyi önce tanımlayın","body":"Bu numuneyle hangi soruya yanıt aradığınızı yazın. Form, mekanizma hareketi ve montaj uyumu farklı deneylerdir. Her birini aynı prototipte çözmeye çalışmak yerine karar sırasına göre ayırın."},{"title":"Revizyonları karşılaştırın","body":"Alternatifleri dosya adında işaretleyin; yalnızca değişen parametreleri bir tabloyla paylaşın. Deneme sonucunu not ederken kullanılan revizyonu ve test koşullarını ekleyin. Böylece yeni numunenin neden istendiği açık kalır."},{"title":"Bütçe ve adet","body":"Görünüş değerlendirmesi için gereken adetle kullanıcı testi için gereken adet aynı olmayabilir. Önce küçük bir doğrulama grubu planlayın. Malzeme, yüzey ve teslim tarihi seçimlerini deneyin amacıyla birlikte değerlendirin."}]'::jsonb,'sector','/brand/industrial/fixture.webp','[{"q":"İlk değerlendirme için ne paylaşmalıyım?","a":"Bu numuneyle hangi soruya yanıt aradığınızı yazın. Form, mekanizma hareketi ve montaj uyumu farklı deneylerdir. Her birini aynı prototipte çözmeye çalışmak yerine karar sırasına göre ayırın."},{"q":"Talebe nasıl başlayabilirim?","a":"3D Studio üzerinden dosyanızı, adet ve kullanım koşullarınızı paylaşabilirsiniz. Dosyanız yoksa fotoğraf, ölçü ve beklenen çıktıyla modelleme değerlendirmesi isteyin."}]'::jsonb,'published','','','','','','','',NULL FROM public.tenants WHERE slug='3dyanimda' ON CONFLICT(tenant_id,path) DO NOTHING;
INSERT INTO public.landing_pages(tenant_id,path,title,summary,sections,kind,image,faq,status,city,district,neighborhood,service,local_context,logistics,evidence,reviewed_at) SELECT id,'/sektorler/sanat-mucevher','Sanat, obje ve takı tasarımı','Heykel, obje ve takı tasarımlarında dijital formu fiziksel ölçekte görerek yüzey ve detay kararlarını geliştirin. 3dyanımda: prototip & kurumsal üretim odağında değerlendirme.','[{"title":"Prototip & kurumsal üretim","body":"3dyanımda: İstanbul’da 3D baskı, 3D tarama ve 3D modelleme. Prototip & kurumsal üretim için proje bazlı üretim. Projenizde 3D baskı, 3D tarama ve 3D modelleme adımlarından hangilerinin gerekli olduğunu kullanım amacınızla birlikte belirleyin."},{"title":"Formun fiziksel etkisi","body":"Ekranda büyük görünen bir detay gerçek ölçekte kaybolabilir. Hedef ölçüyü, tutulacak yüzeyleri ve sergileme yönünü paylaşın. Organik modellerde yüzey sürekliliği ile bilinçli doku kararlarını ayırın."},{"title":"Son işlem planı","body":"Boyama, birleştirme veya başka bir üretim sürecine girdi oluşturma amacı varsa bunu baştan belirtin. Kalıp veya döküm sürecine uygunluk ilgili üretim yöntemiyle ayrıca değerlendirilmelidir. Her baskı malzemesinin her son işlemle uyumlu olduğu varsayılmaz."},{"title":"Tasarım hakları","body":"Üretim için ilettiğiniz modelin kullanım hakkının sizde olduğundan emin olun. Sanatçı adı, eser numarası ve revizyonu dosyada takip edin. Görsel sunum numunesi ile satışa çıkacak nihai ürünün kabul ölçütlerini ayrı belirleyin."}]'::jsonb,'sector','/brand/industrial/fixture.webp','[{"q":"İlk değerlendirme için ne paylaşmalıyım?","a":"Ekranda büyük görünen bir detay gerçek ölçekte kaybolabilir. Hedef ölçüyü, tutulacak yüzeyleri ve sergileme yönünü paylaşın. Organik modellerde yüzey sürekliliği ile bilinçli doku kararlarını ayırın."},{"q":"Talebe nasıl başlayabilirim?","a":"3D Studio üzerinden dosyanızı, adet ve kullanım koşullarınızı paylaşabilirsiniz. Dosyanız yoksa fotoğraf, ölçü ve beklenen çıktıyla modelleme değerlendirmesi isteyin."}]'::jsonb,'published','','','','','','','',NULL FROM public.tenants WHERE slug='3dyanimda' ON CONFLICT(tenant_id,path) DO NOTHING;
INSERT INTO public.landing_pages(tenant_id,path,title,summary,sections,kind,image,faq,status,city,district,neighborhood,service,local_context,logistics,evidence,reviewed_at) SELECT id,'/sektorler/drone-hobi','Drone, robotik ve hobi','Elektronik yerleşimi, kablo yönetimi ve montaj yardımcıları için modelleme ve prototip planınızı oluşturun. 3dyanımda: prototip & kurumsal üretim odağında değerlendirme.','[{"title":"Prototip & kurumsal üretim","body":"3dyanımda: İstanbul’da 3D baskı, 3D tarama ve 3D modelleme. Prototip & kurumsal üretim için proje bazlı üretim. Projenizde 3D baskı, 3D tarama ve 3D modelleme adımlarından hangilerinin gerekli olduğunu kullanım amacınızla birlikte belirleyin."},{"title":"Bileşen yerleşimi","body":"Kart, sensör, bağlantı ve kablo ölçülerini aynı referans sisteminde paylaşın. Montaj sırasında alet erişimi ve kablo bükülme alanını da düşünün. Sadece dış ölçüleri vermek, parçanın sorunsuz monte edileceğini göstermez."},{"title":"Deneme koşulları","body":"Titreşim, dış ortam ve hareketli mekanizma ilişkisini belirtin. Uçuş veya yüksek hız gerektiren kullanımda parça doğrulaması ayrıca ele alınmalıdır. Tasarım numunesini doğrudan güvenlik açısından kritik kullanıma uygun kabul etmeyin."},{"title":"Onarım ve değiştirme","body":"Sık sökülecek kapakları, tüketilecek parçaları ve farklı sürümlerde değişecek bağlantıları işaretleyin. Tasarımın servis kolaylığı prototip üzerinden kontrol edilebilir. Sonraki sipariş için onaylanan dosyayı ve bağlantı ölçülerini saklayın."}]'::jsonb,'sector','/brand/industrial/fixture.webp','[{"q":"İlk değerlendirme için ne paylaşmalıyım?","a":"Kart, sensör, bağlantı ve kablo ölçülerini aynı referans sisteminde paylaşın. Montaj sırasında alet erişimi ve kablo bükülme alanını da düşünün. Sadece dış ölçüleri vermek, parçanın sorunsuz monte edileceğini göstermez."},{"q":"Talebe nasıl başlayabilirim?","a":"3D Studio üzerinden dosyanızı, adet ve kullanım koşullarınızı paylaşabilirsiniz. Dosyanız yoksa fotoğraf, ölçü ve beklenen çıktıyla modelleme değerlendirmesi isteyin."}]'::jsonb,'published','','','','','','','',NULL FROM public.tenants WHERE slug='3dyanimda' ON CONFLICT(tenant_id,path) DO NOTHING;
INSERT INTO public.landing_pages(tenant_id,path,title,summary,sections,kind,image,faq,status,city,district,neighborhood,service,local_context,logistics,evidence,reviewed_at) SELECT id,'/rehber/stl-dosya-hazirlama','STL dosyası hazırlama kontrol listesi','Tekliften önce birim, dış ölçü, yüzey bütünlüğü ve revizyon bilgisini aynı kontrol listesiyle gözden geçirin. 3dyanımda: prototip & kurumsal üretim odağında değerlendirme.','[{"title":"Prototip & kurumsal üretim","body":"3dyanımda: İstanbul’da 3D baskı, 3D tarama ve 3D modelleme. Prototip & kurumsal üretim için proje bazlı üretim. Projenizde 3D baskı, 3D tarama ve 3D modelleme adımlarından hangilerinin gerekli olduğunu kullanım amacınızla birlikte belirleyin."},{"title":"Birim ve ölçek","body":"STL dosyasındaki koordinatları hangi birimde dışa aktardığınızı kaydedin. Önizleyicide dış ölçüleri tasarımınızla karşılaştırın. Milimetre ve inç karışıklığı, görünüş aynı olsa da üretilecek parçanın boyutunu değiştirir."},{"title":"Yüzey ve ayrıntı","body":"Modelde açık yüzey, üst üste geometri veya istenmeyen iç parçalar olup olmadığını CAD yazılımınızda kontrol edin. Görüntüleyicide kesit almak iç ilişkileri anlamayı kolaylaştırır; ancak otomatik üretilebilirlik doğrulamasının yerini tutmaz."},{"title":"Dosya paketi","body":"Parça kodu ve revizyonu dosya adına ekleyin. Adet, kritik ölçü ve kullanım koşullarını ayrı not edin. Birden fazla dosyada aynı kodu farklı revizyonlarla karıştırmayın; onaylanmış sürümü açıkça işaretleyin."}]'::jsonb,'guide','/brand/industrial/fixture.webp','[{"q":"İlk değerlendirme için ne paylaşmalıyım?","a":"STL dosyasındaki koordinatları hangi birimde dışa aktardığınızı kaydedin. Önizleyicide dış ölçüleri tasarımınızla karşılaştırın. Milimetre ve inç karışıklığı, görünüş aynı olsa da üretilecek parçanın boyutunu değiştirir."},{"q":"Talebe nasıl başlayabilirim?","a":"3D Studio üzerinden dosyanızı, adet ve kullanım koşullarınızı paylaşabilirsiniz. Dosyanız yoksa fotoğraf, ölçü ve beklenen çıktıyla modelleme değerlendirmesi isteyin."}]'::jsonb,'published','','','','','','','',NULL FROM public.tenants WHERE slug='3dyanimda' ON CONFLICT(tenant_id,path) DO NOTHING;
INSERT INTO public.landing_pages(tenant_id,path,title,summary,sections,kind,image,faq,status,city,district,neighborhood,service,local_context,logistics,evidence,reviewed_at) SELECT id,'/rehber/tarama-verisinden-cad','Tarama verisinden CAD modeline','Nokta bulutu, yüzey ağı ve düzenlenebilir CAD çıktısını ayırarak tersine mühendislik talebinizi doğru kapsamlandırın. 3dyanımda: prototip & kurumsal üretim odağında değerlendirme.','[{"title":"Prototip & kurumsal üretim","body":"3dyanımda: İstanbul’da 3D baskı, 3D tarama ve 3D modelleme. Prototip & kurumsal üretim için proje bazlı üretim. Projenizde 3D baskı, 3D tarama ve 3D modelleme adımlarından hangilerinin gerekli olduğunu kullanım amacınızla birlikte belirleyin."},{"title":"Hangi veri elinizde?","body":"Tarama sonucunuz nokta verisi veya üçgen yüzey ağı olabilir. Düzenlenebilir katı model gereksinimini ayrıca belirtin. Görüntülenebilen bir dosyanın otomatik olarak parametrik CAD dosyası olduğu varsayılmaz."},{"title":"Fonksiyonel yüzeyler","body":"Delik, mil yatağı, oturma yüzeyi ve bağlantı eksenlerini işaretleyin. Aşınmış veya kırılmış bölgeyi olduğu gibi kopyalamak yerine korunması gereken tasarım ilişkisini açıklayın. Gerekirse sağlam karşı parça da değerlendirmeye eklenir."},{"title":"Teslim ve kontrol","body":"İstenen formatı, revizyon kapsamını ve kontrol edilecek ölçüleri baştan belirleyin. Tarama ile CAD arasındaki farkların nasıl değerlendirileceğini kararlaştırın. Sadece görsel benzerlik, ölçüsel kabulün yerine geçmez."}]'::jsonb,'guide','/brand/industrial/fixture.webp','[{"q":"İlk değerlendirme için ne paylaşmalıyım?","a":"Tarama sonucunuz nokta verisi veya üçgen yüzey ağı olabilir. Düzenlenebilir katı model gereksinimini ayrıca belirtin. Görüntülenebilen bir dosyanın otomatik olarak parametrik CAD dosyası olduğu varsayılmaz."},{"q":"Talebe nasıl başlayabilirim?","a":"3D Studio üzerinden dosyanızı, adet ve kullanım koşullarınızı paylaşabilirsiniz. Dosyanız yoksa fotoğraf, ölçü ve beklenen çıktıyla modelleme değerlendirmesi isteyin."}]'::jsonb,'published','','','','','','','',NULL FROM public.tenants WHERE slug='3dyanimda' ON CONFLICT(tenant_id,path) DO NOTHING;
INSERT INTO public.landing_pages(tenant_id,path,title,summary,sections,kind,image,faq,status,city,district,neighborhood,service,local_context,logistics,evidence,reviewed_at) SELECT id,'/rehber/kesit-nasil-incelenir','3D modelde kesit nasıl incelenir?','Kesit düzlemini kullanarak iç boşlukları, montaj ilişkilerini ve beklenmeyen yüzeyleri görünür hale getirin. 3dyanımda: prototip & kurumsal üretim odağında değerlendirme.','[{"title":"Prototip & kurumsal üretim","body":"3dyanımda: İstanbul’da 3D baskı, 3D tarama ve 3D modelleme. Prototip & kurumsal üretim için proje bazlı üretim. Projenizde 3D baskı, 3D tarama ve 3D modelleme adımlarından hangilerinin gerekli olduğunu kullanım amacınızla birlikte belirleyin."},{"title":"Düzlem yönünü seçin","body":"İncelemek istediğiniz detayın geçtiği ekseni bulun. X, Y ve Z yönlerini sırayla deneyin; sonra düzlemi yavaşça modelin içinden geçirin. Modeli döndürmek, birbirinin arkasında kalan yüzeyleri ayırt etmeye yardımcı olur."},{"title":"Görsel kesitin sınırları","body":"Tarayıcıdaki araç yüzeyleri düzleme göre gizler. Açılan kesiti kapatmaz, takım yolu veya baskı katmanı üretmez. Duvar kalınlığı ya da tolerans raporu gerekiyorsa ölçüm ve üretim yazılımlarındaki uygun araçlarla doğrulama yapın."},{"title":"Bulgunuzu tarif edin","body":"İncelediğiniz ekseni, düzlem konumunu ve sorunlu bölgeyi not edin. Talebe dosyanın aynı revizyonunu ekleyin. Bir ekran görüntüsünde görünen boşluğun tasarım amacı mı, dosya hatası mı olduğunu açıklamadan üretim kararı vermeyin."}]'::jsonb,'guide','/brand/industrial/fixture.webp','[{"q":"İlk değerlendirme için ne paylaşmalıyım?","a":"İncelemek istediğiniz detayın geçtiği ekseni bulun. X, Y ve Z yönlerini sırayla deneyin; sonra düzlemi yavaşça modelin içinden geçirin. Modeli döndürmek, birbirinin arkasında kalan yüzeyleri ayırt etmeye yardımcı olur."},{"q":"Talebe nasıl başlayabilirim?","a":"3D Studio üzerinden dosyanızı, adet ve kullanım koşullarınızı paylaşabilirsiniz. Dosyanız yoksa fotoğraf, ölçü ve beklenen çıktıyla modelleme değerlendirmesi isteyin."}]'::jsonb,'published','','','','','','','',NULL FROM public.tenants WHERE slug='3dyanimda' ON CONFLICT(tenant_id,path) DO NOTHING;
INSERT INTO public.landing_pages(tenant_id,path,title,summary,sections,kind,image,faq,status,city,district,neighborhood,service,local_context,logistics,evidence,reviewed_at) SELECT id,'/rehber/teknik-teklif-dosyasi','Teknik teklif dosyası nasıl hazırlanır?','Satın alma ve teknik ekiplerin aynı dosya üzerinden ilerlemesi için parça, adet, revizyon ve kabul bilgilerini düzenleyin. 3dyanımda: prototip & kurumsal üretim odağında değerlendirme.','[{"title":"Prototip & kurumsal üretim","body":"3dyanımda: İstanbul’da 3D baskı, 3D tarama ve 3D modelleme. Prototip & kurumsal üretim için proje bazlı üretim. Projenizde 3D baskı, 3D tarama ve 3D modelleme adımlarından hangilerinin gerekli olduğunu kullanım amacınızla birlikte belirleyin."},{"title":"Tek bir parça tablosu","body":"Her satırda parça kodu, dosya adı, revizyon ve adet bulunsun. Alternatif tasarımları aynı satırda birleştirmeyin. Hangi parçaların birlikte monte edileceğini belirtin ve montaj çizimini ilişkilendirin."},{"title":"Kabul beklentisi","body":"Kritik ölçüler, görünür yüzeyler, işlevsel kontroller ve numune onayını kimin vereceği talepte yer alsın. Belgelenmeyen bir beklentinin teklif kapsamına otomatik girdiğini varsaymayın. Teslim dosyası ve fiziksel ürün kapsamını ayrı yazın."},{"title":"Takvim ve değişiklik","body":"Hedef tarihi, ara onay adımlarını ve revizyon için ayrılan süreyi belirtin. Talep sonrası geometri veya adet değişirse teklif yeniden değerlendirilebilir. Onaylanan sürümü teknik ekip ve satın alma arasında ortak referans yapın."}]'::jsonb,'guide','/brand/industrial/fixture.webp','[{"q":"İlk değerlendirme için ne paylaşmalıyım?","a":"Her satırda parça kodu, dosya adı, revizyon ve adet bulunsun. Alternatif tasarımları aynı satırda birleştirmeyin. Hangi parçaların birlikte monte edileceğini belirtin ve montaj çizimini ilişkilendirin."},{"q":"Talebe nasıl başlayabilirim?","a":"3D Studio üzerinden dosyanızı, adet ve kullanım koşullarınızı paylaşabilirsiniz. Dosyanız yoksa fotoğraf, ölçü ve beklenen çıktıyla modelleme değerlendirmesi isteyin."}]'::jsonb,'published','','','','','','','',NULL FROM public.tenants WHERE slug='3dyanimda' ON CONFLICT(tenant_id,path) DO NOTHING;
INSERT INTO public.landing_pages(tenant_id,path,title,summary,sections,kind,image,faq,status,city,district,neighborhood,service,local_context,logistics,evidence,reviewed_at) SELECT id,'/rehber/malzeme-secim-sorulari','Malzeme seçmeden önce sorulacak sorular','Malzeme kararını yalnızca isim veya renge göre değil, parçanın işlevi ve çalışma koşullarına göre hazırlayın. 3dyanımda: prototip & kurumsal üretim odağında değerlendirme.','[{"title":"Prototip & kurumsal üretim","body":"3dyanımda: İstanbul’da 3D baskı, 3D tarama ve 3D modelleme. Prototip & kurumsal üretim için proje bazlı üretim. Projenizde 3D baskı, 3D tarama ve 3D modelleme adımlarından hangilerinin gerekli olduğunu kullanım amacınızla birlikte belirleyin."},{"title":"Ortamı tanımlayın","body":"Parça nerede çalışacak? Sıcaklık, güneş, nem ve kimyasal temas var mı? Sürekli yük mü taşıyacak, aralıklı darbe mi alacak? Bu sorulara sayısal bilgi verebiliyorsanız talebe ekleyin; bilinmeyen koşulları da açıkça yazın."},{"title":"Geometriyi birlikte düşünün","body":"İnce bağlantılar, esneyen tırnaklar ve büyük düz yüzeyler farklı tasarım değerlendirmeleri gerektirir. Malzeme, yönlendirme ve üretim yöntemi birlikte ele alınmalıdır. Sadece doluluk oranını artırmak her işlevsel problemi çözmez."},{"title":"Numuneyle karar verin","body":"Kritik kullanımlarda numuneyi hedef ortama uygun bir kontrol planıyla değerlendirin. Malzeme veri sayfasını, üretim ayarlarını ve test koşullarını birbirine karıştırmayın. Nihai kabul ölçütünü üretimden önce belirleyin."}]'::jsonb,'guide','/brand/industrial/fixture.webp','[{"q":"İlk değerlendirme için ne paylaşmalıyım?","a":"Parça nerede çalışacak? Sıcaklık, güneş, nem ve kimyasal temas var mı? Sürekli yük mü taşıyacak, aralıklı darbe mi alacak? Bu sorulara sayısal bilgi verebiliyorsanız talebe ekleyin; bilinmeyen koşulları da açıkça yazın."},{"q":"Talebe nasıl başlayabilirim?","a":"3D Studio üzerinden dosyanızı, adet ve kullanım koşullarınızı paylaşabilirsiniz. Dosyanız yoksa fotoğraf, ölçü ve beklenen çıktıyla modelleme değerlendirmesi isteyin."}]'::jsonb,'published','','','','','','','',NULL FROM public.tenants WHERE slug='3dyanimda' ON CONFLICT(tenant_id,path) DO NOTHING;
INSERT INTO public.landing_pages(tenant_id,path,title,summary,sections,kind,image,faq,status,city,district,neighborhood,service,local_context,logistics,evidence,reviewed_at) SELECT id,'/rehber/maket-olcek-planlama','Maket ölçeği ve parçalara ayırma','Mimari modelin fiziksel ölçüsünü, okunabilir detayını ve taşıma ihtiyacını tek üretim planında birleştirin. 3dyanımda: prototip & kurumsal üretim odağında değerlendirme.','[{"title":"Prototip & kurumsal üretim","body":"3dyanımda: İstanbul’da 3D baskı, 3D tarama ve 3D modelleme. Prototip & kurumsal üretim için proje bazlı üretim. Projenizde 3D baskı, 3D tarama ve 3D modelleme adımlarından hangilerinin gerekli olduğunu kullanım amacınızla birlikte belirleyin."},{"title":"Ölçeği hesaplayın","body":"Gerçek boyutu ölçek paydasına bölerek maket boyutunu bulun. Örneğin 10 metrelik bir uzunluk 1:100 ölçekte 100 milimetredir. Kaynak dosyanın metre veya milimetre oluşunu ayrıca kontrol edin."},{"title":"Detay seviyesini seçin","body":"Pencere, korkuluk ve peyzaj gibi öğeleri her ölçekte aynı biçimde üretmek uygun olmayabilir. Anlatım açısından gerekli ayrıntıları listeleyin. Fiziksel sınırlar nedeniyle sadeleştirilecek bölgeler için dijital onay alın."},{"title":"Taşıma ve montaj","body":"Taban ölçüsü, birleşim yerleri ve sökülebilir parçaları kutulama planıyla birlikte değerlendirin. Parçaları kodlayın ve yerleşim şemasını saklayın. Sergileme sırasında sık taşınacak bir maket için servis erişimini de planlayın."}]'::jsonb,'guide','/brand/industrial/fixture.webp','[{"q":"İlk değerlendirme için ne paylaşmalıyım?","a":"Gerçek boyutu ölçek paydasına bölerek maket boyutunu bulun. Örneğin 10 metrelik bir uzunluk 1:100 ölçekte 100 milimetredir. Kaynak dosyanın metre veya milimetre oluşunu ayrıca kontrol edin."},{"q":"Talebe nasıl başlayabilirim?","a":"3D Studio üzerinden dosyanızı, adet ve kullanım koşullarınızı paylaşabilirsiniz. Dosyanız yoksa fotoğraf, ölçü ve beklenen çıktıyla modelleme değerlendirmesi isteyin."}]'::jsonb,'published','','','','','','','',NULL FROM public.tenants WHERE slug='3dyanimda' ON CONFLICT(tenant_id,path) DO NOTHING;
INSERT INTO public.landing_pages(tenant_id,path,title,summary,sections,kind,image,faq,status,city,district,neighborhood,service,local_context,logistics,evidence,reviewed_at) SELECT id,'/rehber/numune-kabul-plani','Numune kabul planı','Bir prototipin hangi koşullarda onaylanacağını üretimden önce tanımlayarak revizyon görüşmelerini somutlaştırın. 3dyanımda: prototip & kurumsal üretim odağında değerlendirme.','[{"title":"Prototip & kurumsal üretim","body":"3dyanımda: İstanbul’da 3D baskı, 3D tarama ve 3D modelleme. Prototip & kurumsal üretim için proje bazlı üretim. Projenizde 3D baskı, 3D tarama ve 3D modelleme adımlarından hangilerinin gerekli olduğunu kullanım amacınızla birlikte belirleyin."},{"title":"Kontrol maddeleri","body":"Görünüş, montaj uyumu, ölçü ve işlevi ayrı maddeler halinde yazın. Her maddenin kontrol yöntemini ve karar verecek kişiyi belirleyin. Sadece fotoğraftan onaylanamayacak beklentileri fiziksel deneme aşamasına bırakın."},{"title":"Kayıt düzeni","body":"Numunenin dosya revizyonu, malzemesi, adedi ve test tarihi bir arada tutulmalıdır. Test sırasında yapılan elle düzeltmeler varsa bunları da kaydedin. Yeni baskıda aynı düzeltmenin yeniden gerekmemesi için dijital modele geri işleyin."},{"title":"Onaydan tekrar siparişe","body":"Hangi maddelerin geçtiğini ve hangilerinin açık kaldığını listeleyin. Koşullu onayı nihai onaydan ayırın. Tekrar sipariş verirken aynı revizyonu, değişen adetleri ve yeni kullanım koşullarını belirtin."}]'::jsonb,'guide','/brand/industrial/fixture.webp','[{"q":"İlk değerlendirme için ne paylaşmalıyım?","a":"Görünüş, montaj uyumu, ölçü ve işlevi ayrı maddeler halinde yazın. Her maddenin kontrol yöntemini ve karar verecek kişiyi belirleyin. Sadece fotoğraftan onaylanamayacak beklentileri fiziksel deneme aşamasına bırakın."},{"q":"Talebe nasıl başlayabilirim?","a":"3D Studio üzerinden dosyanızı, adet ve kullanım koşullarınızı paylaşabilirsiniz. Dosyanız yoksa fotoğraf, ölçü ve beklenen çıktıyla modelleme değerlendirmesi isteyin."}]'::jsonb,'published','','','','','','','',NULL FROM public.tenants WHERE slug='3dyanimda' ON CONFLICT(tenant_id,path) DO NOTHING;
INSERT INTO public.landing_pages(tenant_id,path,title,summary,sections,kind,image,faq,status,city,district,neighborhood,service,local_context,logistics,evidence,reviewed_at) SELECT id,'/cozumler/kurumsal-proje-yonetimi','Kurumsal proje ve tedarik süreci','Teknik ekip, satın alma ve üretim arasında dosya, onay ve tekrar sipariş akışını aynı proje kapsamına bağlayın. 3dyanımda: prototip & kurumsal üretim odağında değerlendirme.','[{"title":"Prototip & kurumsal üretim","body":"3dyanımda: İstanbul’da 3D baskı, 3D tarama ve 3D modelleme. Prototip & kurumsal üretim için proje bazlı üretim. Projenizde 3D baskı, 3D tarama ve 3D modelleme adımlarından hangilerinin gerekli olduğunu kullanım amacınızla birlikte belirleyin."},{"title":"Talep ve kapsam","body":"Projenin kullanım amacını, parça listesini ve hedef tarihini paylaşın. Modelleme, tarama, üretim ve son işlem kalemlerini ayrı değerlendirin. Teklifte hangi dosya ve fiziksel çıktıların teslim edileceği açıkça belirtilmelidir."},{"title":"Numune ve revizyon","body":"İlk numunenin kabul maddelerini ve onay sorumlusunu belirleyin. Değişiklik taleplerini tek bir revizyon listesinde toplayın. Yeni geometri, adet veya teslim koşulu fiyat ve takvimin tekrar değerlendirilmesini gerektirebilir."},{"title":"Tekrar sipariş","body":"Onaylı dosyanın parça kodunu ve revizyonunu saklayın. Tekrar siparişte yalnızca eski fotoğraf yerine bu referansı kullanın. Çalışma ortamı veya kullanım amacı değiştiyse teknik değerlendirmeyi yenileyin."}]'::jsonb,'solution','/brand/industrial/fixture.webp','[{"q":"İlk değerlendirme için ne paylaşmalıyım?","a":"Projenin kullanım amacını, parça listesini ve hedef tarihini paylaşın. Modelleme, tarama, üretim ve son işlem kalemlerini ayrı değerlendirin. Teklifte hangi dosya ve fiziksel çıktıların teslim edileceği açıkça belirtilmelidir."},{"q":"Talebe nasıl başlayabilirim?","a":"3D Studio üzerinden dosyanızı, adet ve kullanım koşullarınızı paylaşabilirsiniz. Dosyanız yoksa fotoğraf, ölçü ve beklenen çıktıyla modelleme değerlendirmesi isteyin."}]'::jsonb,'published','','','','','','','',NULL FROM public.tenants WHERE slug='3dyanimda' ON CONFLICT(tenant_id,path) DO NOTHING;
INSERT INTO public.landing_pages(tenant_id,path,title,summary,sections,kind,image,faq,status,city,district,neighborhood,service,local_context,logistics,evidence,reviewed_at) SELECT id,'/sektorler/endustriyel','Endüstriyel üretim','Üretim hattındaki özel aparat, montaj yardımcısı ve düşük adetli parça ihtiyaçlarını aynı teknik briefte toplayın. 3dsanayi: endüstriyel parça & fikstür odağında değerlendirme.','[{"title":"Endüstriyel parça & fikstür","body":"3dsanayi: İstanbul’da 3D baskı, 3D tarama ve 3D modelleme. Endüstriyel parça & fikstür için proje bazlı üretim. Projenizde 3D baskı, 3D tarama ve 3D modelleme adımlarından hangilerinin gerekli olduğunu kullanım amacınızla birlikte belirleyin."},{"title":"Hattaki görevi tarif edin","body":"Parçanın hangi operasyonda kullanıldığını, operatörün nasıl tuttuğunu ve hangi yüzeylerin referans alındığını açıklayın. Çevrim sırasında oluşan yük, sıcaklık ve kimyasal temas bilgisi üretim kararının girdisidir. Mevcut çizim varsa kritik ölçüleri ayrı işaretleyin."},{"title":"Pilot parçadan onaylı revizyona","body":"İlk numuneyi gerçek montaj noktasında değerlendirecek kişiyi belirleyin. Uyum, erişim ve operatör kullanımı ayrı kontrol başlıkları olmalıdır. Numune üzerinde yapılan değişiklikleri çizim revizyonuna işleyin; seri talebi yalnızca onaylanan dosyaya bağlayın."},{"title":"Satın alma dosyası","body":"Talebe parça kodu, adet, malzeme beklentisi ve kabul ölçütlerini ekleyin. Birden fazla parçanın aynı siparişte değerlendirilmesi gerekiyorsa dosya adlarını adet tablosuyla eşleştirin. Tekrarlı siparişlerde önceki revizyon ve değişen koşulları belirtin."}]'::jsonb,'sector','/brand/industrial/fixture.webp','[{"q":"İlk değerlendirme için ne paylaşmalıyım?","a":"Parçanın hangi operasyonda kullanıldığını, operatörün nasıl tuttuğunu ve hangi yüzeylerin referans alındığını açıklayın. Çevrim sırasında oluşan yük, sıcaklık ve kimyasal temas bilgisi üretim kararının girdisidir. Mevcut çizim varsa kritik ölçüleri ayrı işaretleyin."},{"q":"Talebe nasıl başlayabilirim?","a":"3D Studio üzerinden dosyanızı, adet ve kullanım koşullarınızı paylaşabilirsiniz. Dosyanız yoksa fotoğraf, ölçü ve beklenen çıktıyla modelleme değerlendirmesi isteyin."}]'::jsonb,'published','','','','','','','',NULL FROM public.tenants WHERE slug='3dsanayi' ON CONFLICT(tenant_id,path) DO NOTHING;
INSERT INTO public.landing_pages(tenant_id,path,title,summary,sections,kind,image,faq,status,city,district,neighborhood,service,local_context,logistics,evidence,reviewed_at) SELECT id,'/sektorler/otomotiv','Otomotiv ve yedek parça','Trim, kapak, klips ve prototip parçalarında numuneden modele uzanan süreci kullanım koşullarıyla birlikte planlayın. 3dsanayi: endüstriyel parça & fikstür odağında değerlendirme.','[{"title":"Endüstriyel parça & fikstür","body":"3dsanayi: İstanbul’da 3D baskı, 3D tarama ve 3D modelleme. Endüstriyel parça & fikstür için proje bazlı üretim. Projenizde 3D baskı, 3D tarama ve 3D modelleme adımlarından hangilerinin gerekli olduğunu kullanım amacınızla birlikte belirleyin."},{"title":"Montaj ilişkisini koruyun","body":"Tek başına kırık parçanın fotoğrafı her zaman yeterli değildir. Parçanın takıldığı bölgeyi, sağlam eşini ve bağlantı elemanlarını da gösterin. Geçme yönü ve esnemesi gereken bölgeler işaretlenirse modelleme kapsamı daha doğru belirlenir."},{"title":"Ortam koşullarını paylaşın","body":"İç mekân, güneş gören bölge veya motor çevresi farklı koşullar taşır. Sıcaklık, titreşim, kimyasal temas ve beklenen kullanım ömrünü anlatın. Görünüş numunesi ile işlevsel kullanım parçasını aynı kabul kriteriyle değerlendirmeyin."},{"title":"Doğrulama kapsamı","body":"Emniyet açısından kritik bir parçanın yeniden üretilmesi ayrıca mühendislik doğrulaması gerektirir. Talepte parçanın görevini açıkça belirtin. Prototipin montaja oturması, tek başına güvenli kullanım onayı anlamına gelmez."}]'::jsonb,'sector','/brand/industrial/fixture.webp','[{"q":"İlk değerlendirme için ne paylaşmalıyım?","a":"Tek başına kırık parçanın fotoğrafı her zaman yeterli değildir. Parçanın takıldığı bölgeyi, sağlam eşini ve bağlantı elemanlarını da gösterin. Geçme yönü ve esnemesi gereken bölgeler işaretlenirse modelleme kapsamı daha doğru belirlenir."},{"q":"Talebe nasıl başlayabilirim?","a":"3D Studio üzerinden dosyanızı, adet ve kullanım koşullarınızı paylaşabilirsiniz. Dosyanız yoksa fotoğraf, ölçü ve beklenen çıktıyla modelleme değerlendirmesi isteyin."}]'::jsonb,'published','','','','','','','',NULL FROM public.tenants WHERE slug='3dsanayi' ON CONFLICT(tenant_id,path) DO NOTHING;
INSERT INTO public.landing_pages(tenant_id,path,title,summary,sections,kind,image,faq,status,city,district,neighborhood,service,local_context,logistics,evidence,reviewed_at) SELECT id,'/sektorler/mimari-tasarim','Mimari ve tasarım','Kütle, cephe ve yerleşim maketlerinde ölçeği, gösterilecek detayları ve taşıma planını üretimden önce netleştirin. 3dsanayi: endüstriyel parça & fikstür odağında değerlendirme.','[{"title":"Endüstriyel parça & fikstür","body":"3dsanayi: İstanbul’da 3D baskı, 3D tarama ve 3D modelleme. Endüstriyel parça & fikstür için proje bazlı üretim. Projenizde 3D baskı, 3D tarama ve 3D modelleme adımlarından hangilerinin gerekli olduğunu kullanım amacınızla birlikte belirleyin."},{"title":"Ölçekte okunabilirlik","body":"Kaynak modelin birimini, hedef maket ölçeğini ve bitmiş taban ölçüsünü paylaşın. Cephedeki çok küçük detayların fiziksel makette nasıl temsil edileceğini kararlaştırın. Peyzaj, kütle ve iç mekân farklı ayrıntı seviyelerinde ele alınabilir."},{"title":"Bölünebilir üretim","body":"Maketin sergileneceği alan ve taşınacağı kutu boyutu, parçalara ayırma kararını etkiler. Birleşim yerlerini görünür cephelerden uzaklaştırmak veya sökülebilir kütleler kullanmak tasarım aşamasında değerlendirilebilir. Aydınlatma ve kablo kanalları ayrıca belirtilmelidir."},{"title":"Sunum onayı","body":"Renk, yüzey, etiket ve taban beklentisini referanslarla anlatın. Önce dijital yerleşim, sonra kritik bir detayın numunesi üzerinden karar verin. Son teslimden önce parça listesi ve yerleşim şemasını birlikte kontrol edin."}]'::jsonb,'sector','/brand/industrial/fixture.webp','[{"q":"İlk değerlendirme için ne paylaşmalıyım?","a":"Kaynak modelin birimini, hedef maket ölçeğini ve bitmiş taban ölçüsünü paylaşın. Cephedeki çok küçük detayların fiziksel makette nasıl temsil edileceğini kararlaştırın. Peyzaj, kütle ve iç mekân farklı ayrıntı seviyelerinde ele alınabilir."},{"q":"Talebe nasıl başlayabilirim?","a":"3D Studio üzerinden dosyanızı, adet ve kullanım koşullarınızı paylaşabilirsiniz. Dosyanız yoksa fotoğraf, ölçü ve beklenen çıktıyla modelleme değerlendirmesi isteyin."}]'::jsonb,'published','','','','','','','',NULL FROM public.tenants WHERE slug='3dsanayi' ON CONFLICT(tenant_id,path) DO NOTHING;
INSERT INTO public.landing_pages(tenant_id,path,title,summary,sections,kind,image,faq,status,city,district,neighborhood,service,local_context,logistics,evidence,reviewed_at) SELECT id,'/sektorler/medikal','Medikal tasarım ve eğitim','Anlatım, eğitim ve tasarım değerlendirmesi için anatomik gösterim ve cihaz gövdesi prototiplerinin kapsamını belirleyin. 3dsanayi: endüstriyel parça & fikstür odağında değerlendirme.','[{"title":"Endüstriyel parça & fikstür","body":"3dsanayi: İstanbul’da 3D baskı, 3D tarama ve 3D modelleme. Endüstriyel parça & fikstür için proje bazlı üretim. Projenizde 3D baskı, 3D tarama ve 3D modelleme adımlarından hangilerinin gerekli olduğunu kullanım amacınızla birlikte belirleyin."},{"title":"Kullanım amacını ayırın","body":"Eğitimde gösterim, cihazın form kontrolü ve klinik kullanım birbirinden farklı kapsamlar taşır. Talebinizin hangi amaçla kullanılacağını açıkça yazın. Bu sayfadaki prototipleme yaklaşımı klinik uygunluk, sterilizasyon veya hasta temasına ilişkin bir onay değildir."},{"title":"Veri paylaşımı","body":"Gerekli dosya formatını ve görüntüleme beklentisini teknik ekiple belirleyin. Kişisel bilgi içeren görüntü veya dosyaları paylaşmadan önce yetki ve anonimleştirme süreçlerinizi tamamlayın. Teklif aşamasında mümkünse kimlik bilgisi içermeyen geometriyle başlayın."},{"title":"Eğitim modelinin kabulü","body":"Gösterilecek yapıları, renk ayrımını, sökülebilir bölümleri ve kullanılacak ölçeği listeleyin. Modelin anlatım amacına uygunluğunu konu uzmanı değerlendirmelidir. Dijital onay ile fiziksel yüzey beklentisini ayrı adımlarda ele alın."}]'::jsonb,'sector','/brand/industrial/fixture.webp','[{"q":"İlk değerlendirme için ne paylaşmalıyım?","a":"Eğitimde gösterim, cihazın form kontrolü ve klinik kullanım birbirinden farklı kapsamlar taşır. Talebinizin hangi amaçla kullanılacağını açıkça yazın. Bu sayfadaki prototipleme yaklaşımı klinik uygunluk, sterilizasyon veya hasta temasına ilişkin bir onay değildir."},{"q":"Talebe nasıl başlayabilirim?","a":"3D Studio üzerinden dosyanızı, adet ve kullanım koşullarınızı paylaşabilirsiniz. Dosyanız yoksa fotoğraf, ölçü ve beklenen çıktıyla modelleme değerlendirmesi isteyin."}]'::jsonb,'published','','','','','','','',NULL FROM public.tenants WHERE slug='3dsanayi' ON CONFLICT(tenant_id,path) DO NOTHING;
INSERT INTO public.landing_pages(tenant_id,path,title,summary,sections,kind,image,faq,status,city,district,neighborhood,service,local_context,logistics,evidence,reviewed_at) SELECT id,'/sektorler/savunma-havacilik','Havacılık ve teknik Ar-Ge','Form kontrolü, ergonomi ve montaj gösterimi için kullanılan teknik prototipleri izlenebilir bir dosya akışıyla planlayın. 3dsanayi: endüstriyel parça & fikstür odağında değerlendirme.','[{"title":"Endüstriyel parça & fikstür","body":"3dsanayi: İstanbul’da 3D baskı, 3D tarama ve 3D modelleme. Endüstriyel parça & fikstür için proje bazlı üretim. Projenizde 3D baskı, 3D tarama ve 3D modelleme adımlarından hangilerinin gerekli olduğunu kullanım amacınızla birlikte belirleyin."},{"title":"Kapsam ve veri sınırı","body":"Paylaşıma yetkili olduğunuz çizimleri ve kullanım amacı bilgisini talebe ekleyin. İlk değerlendirme için gerekli olmayan hassas proje detaylarını kapsam dışında tutun. Dosya erişimi, gizlilik ve revizyon sorumluları teklif öncesinde belirlenmelidir."},{"title":"Gösterim ve montaj prototipi","body":"Ergonomi maketi, bağlantı yerleşimi veya dış form numunesinde hangi kararın doğrulanacağını yazın. Görsel prototipin uçuşa elverişlilik veya işlevsel parça sertifikası sağlamadığını proje içinde açıkça ayırın. Kritik işlevler ayrı doğrulama planı gerektirir."},{"title":"İzlenebilir değerlendirme","body":"Dosya adı, parça kodu, revizyon, talep sahibi ve kabul kontrolünü ortak tabloda tutun. Fiziksel numune üzerindeki değişiklikleri dijital modele geri işleyin. Tekrar üretimde onaylı dosyanın aynı olduğundan emin olun."}]'::jsonb,'sector','/brand/industrial/fixture.webp','[{"q":"İlk değerlendirme için ne paylaşmalıyım?","a":"Paylaşıma yetkili olduğunuz çizimleri ve kullanım amacı bilgisini talebe ekleyin. İlk değerlendirme için gerekli olmayan hassas proje detaylarını kapsam dışında tutun. Dosya erişimi, gizlilik ve revizyon sorumluları teklif öncesinde belirlenmelidir."},{"q":"Talebe nasıl başlayabilirim?","a":"3D Studio üzerinden dosyanızı, adet ve kullanım koşullarınızı paylaşabilirsiniz. Dosyanız yoksa fotoğraf, ölçü ve beklenen çıktıyla modelleme değerlendirmesi isteyin."}]'::jsonb,'published','','','','','','','',NULL FROM public.tenants WHERE slug='3dsanayi' ON CONFLICT(tenant_id,path) DO NOTHING;
INSERT INTO public.landing_pages(tenant_id,path,title,summary,sections,kind,image,faq,status,city,district,neighborhood,service,local_context,logistics,evidence,reviewed_at) SELECT id,'/sektorler/egitim-arge','Eğitim ve Ar-Ge','Fikrinizi test edilebilir numunelere ayırın; bir sonraki tasarım kararını verecek prototipi üretin. 3dsanayi: endüstriyel parça & fikstür odağında değerlendirme.','[{"title":"Endüstriyel parça & fikstür","body":"3dsanayi: İstanbul’da 3D baskı, 3D tarama ve 3D modelleme. Endüstriyel parça & fikstür için proje bazlı üretim. Projenizde 3D baskı, 3D tarama ve 3D modelleme adımlarından hangilerinin gerekli olduğunu kullanım amacınızla birlikte belirleyin."},{"title":"Deneyi önce tanımlayın","body":"Bu numuneyle hangi soruya yanıt aradığınızı yazın. Form, mekanizma hareketi ve montaj uyumu farklı deneylerdir. Her birini aynı prototipte çözmeye çalışmak yerine karar sırasına göre ayırın."},{"title":"Revizyonları karşılaştırın","body":"Alternatifleri dosya adında işaretleyin; yalnızca değişen parametreleri bir tabloyla paylaşın. Deneme sonucunu not ederken kullanılan revizyonu ve test koşullarını ekleyin. Böylece yeni numunenin neden istendiği açık kalır."},{"title":"Bütçe ve adet","body":"Görünüş değerlendirmesi için gereken adetle kullanıcı testi için gereken adet aynı olmayabilir. Önce küçük bir doğrulama grubu planlayın. Malzeme, yüzey ve teslim tarihi seçimlerini deneyin amacıyla birlikte değerlendirin."}]'::jsonb,'sector','/brand/industrial/fixture.webp','[{"q":"İlk değerlendirme için ne paylaşmalıyım?","a":"Bu numuneyle hangi soruya yanıt aradığınızı yazın. Form, mekanizma hareketi ve montaj uyumu farklı deneylerdir. Her birini aynı prototipte çözmeye çalışmak yerine karar sırasına göre ayırın."},{"q":"Talebe nasıl başlayabilirim?","a":"3D Studio üzerinden dosyanızı, adet ve kullanım koşullarınızı paylaşabilirsiniz. Dosyanız yoksa fotoğraf, ölçü ve beklenen çıktıyla modelleme değerlendirmesi isteyin."}]'::jsonb,'published','','','','','','','',NULL FROM public.tenants WHERE slug='3dsanayi' ON CONFLICT(tenant_id,path) DO NOTHING;
INSERT INTO public.landing_pages(tenant_id,path,title,summary,sections,kind,image,faq,status,city,district,neighborhood,service,local_context,logistics,evidence,reviewed_at) SELECT id,'/sektorler/sanat-mucevher','Sanat, obje ve takı tasarımı','Heykel, obje ve takı tasarımlarında dijital formu fiziksel ölçekte görerek yüzey ve detay kararlarını geliştirin. 3dsanayi: endüstriyel parça & fikstür odağında değerlendirme.','[{"title":"Endüstriyel parça & fikstür","body":"3dsanayi: İstanbul’da 3D baskı, 3D tarama ve 3D modelleme. Endüstriyel parça & fikstür için proje bazlı üretim. Projenizde 3D baskı, 3D tarama ve 3D modelleme adımlarından hangilerinin gerekli olduğunu kullanım amacınızla birlikte belirleyin."},{"title":"Formun fiziksel etkisi","body":"Ekranda büyük görünen bir detay gerçek ölçekte kaybolabilir. Hedef ölçüyü, tutulacak yüzeyleri ve sergileme yönünü paylaşın. Organik modellerde yüzey sürekliliği ile bilinçli doku kararlarını ayırın."},{"title":"Son işlem planı","body":"Boyama, birleştirme veya başka bir üretim sürecine girdi oluşturma amacı varsa bunu baştan belirtin. Kalıp veya döküm sürecine uygunluk ilgili üretim yöntemiyle ayrıca değerlendirilmelidir. Her baskı malzemesinin her son işlemle uyumlu olduğu varsayılmaz."},{"title":"Tasarım hakları","body":"Üretim için ilettiğiniz modelin kullanım hakkının sizde olduğundan emin olun. Sanatçı adı, eser numarası ve revizyonu dosyada takip edin. Görsel sunum numunesi ile satışa çıkacak nihai ürünün kabul ölçütlerini ayrı belirleyin."}]'::jsonb,'sector','/brand/industrial/fixture.webp','[{"q":"İlk değerlendirme için ne paylaşmalıyım?","a":"Ekranda büyük görünen bir detay gerçek ölçekte kaybolabilir. Hedef ölçüyü, tutulacak yüzeyleri ve sergileme yönünü paylaşın. Organik modellerde yüzey sürekliliği ile bilinçli doku kararlarını ayırın."},{"q":"Talebe nasıl başlayabilirim?","a":"3D Studio üzerinden dosyanızı, adet ve kullanım koşullarınızı paylaşabilirsiniz. Dosyanız yoksa fotoğraf, ölçü ve beklenen çıktıyla modelleme değerlendirmesi isteyin."}]'::jsonb,'published','','','','','','','',NULL FROM public.tenants WHERE slug='3dsanayi' ON CONFLICT(tenant_id,path) DO NOTHING;
INSERT INTO public.landing_pages(tenant_id,path,title,summary,sections,kind,image,faq,status,city,district,neighborhood,service,local_context,logistics,evidence,reviewed_at) SELECT id,'/sektorler/drone-hobi','Drone, robotik ve hobi','Elektronik yerleşimi, kablo yönetimi ve montaj yardımcıları için modelleme ve prototip planınızı oluşturun. 3dsanayi: endüstriyel parça & fikstür odağında değerlendirme.','[{"title":"Endüstriyel parça & fikstür","body":"3dsanayi: İstanbul’da 3D baskı, 3D tarama ve 3D modelleme. Endüstriyel parça & fikstür için proje bazlı üretim. Projenizde 3D baskı, 3D tarama ve 3D modelleme adımlarından hangilerinin gerekli olduğunu kullanım amacınızla birlikte belirleyin."},{"title":"Bileşen yerleşimi","body":"Kart, sensör, bağlantı ve kablo ölçülerini aynı referans sisteminde paylaşın. Montaj sırasında alet erişimi ve kablo bükülme alanını da düşünün. Sadece dış ölçüleri vermek, parçanın sorunsuz monte edileceğini göstermez."},{"title":"Deneme koşulları","body":"Titreşim, dış ortam ve hareketli mekanizma ilişkisini belirtin. Uçuş veya yüksek hız gerektiren kullanımda parça doğrulaması ayrıca ele alınmalıdır. Tasarım numunesini doğrudan güvenlik açısından kritik kullanıma uygun kabul etmeyin."},{"title":"Onarım ve değiştirme","body":"Sık sökülecek kapakları, tüketilecek parçaları ve farklı sürümlerde değişecek bağlantıları işaretleyin. Tasarımın servis kolaylığı prototip üzerinden kontrol edilebilir. Sonraki sipariş için onaylanan dosyayı ve bağlantı ölçülerini saklayın."}]'::jsonb,'sector','/brand/industrial/fixture.webp','[{"q":"İlk değerlendirme için ne paylaşmalıyım?","a":"Kart, sensör, bağlantı ve kablo ölçülerini aynı referans sisteminde paylaşın. Montaj sırasında alet erişimi ve kablo bükülme alanını da düşünün. Sadece dış ölçüleri vermek, parçanın sorunsuz monte edileceğini göstermez."},{"q":"Talebe nasıl başlayabilirim?","a":"3D Studio üzerinden dosyanızı, adet ve kullanım koşullarınızı paylaşabilirsiniz. Dosyanız yoksa fotoğraf, ölçü ve beklenen çıktıyla modelleme değerlendirmesi isteyin."}]'::jsonb,'published','','','','','','','',NULL FROM public.tenants WHERE slug='3dsanayi' ON CONFLICT(tenant_id,path) DO NOTHING;
INSERT INTO public.landing_pages(tenant_id,path,title,summary,sections,kind,image,faq,status,city,district,neighborhood,service,local_context,logistics,evidence,reviewed_at) SELECT id,'/rehber/stl-dosya-hazirlama','STL dosyası hazırlama kontrol listesi','Tekliften önce birim, dış ölçü, yüzey bütünlüğü ve revizyon bilgisini aynı kontrol listesiyle gözden geçirin. 3dsanayi: endüstriyel parça & fikstür odağında değerlendirme.','[{"title":"Endüstriyel parça & fikstür","body":"3dsanayi: İstanbul’da 3D baskı, 3D tarama ve 3D modelleme. Endüstriyel parça & fikstür için proje bazlı üretim. Projenizde 3D baskı, 3D tarama ve 3D modelleme adımlarından hangilerinin gerekli olduğunu kullanım amacınızla birlikte belirleyin."},{"title":"Birim ve ölçek","body":"STL dosyasındaki koordinatları hangi birimde dışa aktardığınızı kaydedin. Önizleyicide dış ölçüleri tasarımınızla karşılaştırın. Milimetre ve inç karışıklığı, görünüş aynı olsa da üretilecek parçanın boyutunu değiştirir."},{"title":"Yüzey ve ayrıntı","body":"Modelde açık yüzey, üst üste geometri veya istenmeyen iç parçalar olup olmadığını CAD yazılımınızda kontrol edin. Görüntüleyicide kesit almak iç ilişkileri anlamayı kolaylaştırır; ancak otomatik üretilebilirlik doğrulamasının yerini tutmaz."},{"title":"Dosya paketi","body":"Parça kodu ve revizyonu dosya adına ekleyin. Adet, kritik ölçü ve kullanım koşullarını ayrı not edin. Birden fazla dosyada aynı kodu farklı revizyonlarla karıştırmayın; onaylanmış sürümü açıkça işaretleyin."}]'::jsonb,'guide','/brand/industrial/fixture.webp','[{"q":"İlk değerlendirme için ne paylaşmalıyım?","a":"STL dosyasındaki koordinatları hangi birimde dışa aktardığınızı kaydedin. Önizleyicide dış ölçüleri tasarımınızla karşılaştırın. Milimetre ve inç karışıklığı, görünüş aynı olsa da üretilecek parçanın boyutunu değiştirir."},{"q":"Talebe nasıl başlayabilirim?","a":"3D Studio üzerinden dosyanızı, adet ve kullanım koşullarınızı paylaşabilirsiniz. Dosyanız yoksa fotoğraf, ölçü ve beklenen çıktıyla modelleme değerlendirmesi isteyin."}]'::jsonb,'published','','','','','','','',NULL FROM public.tenants WHERE slug='3dsanayi' ON CONFLICT(tenant_id,path) DO NOTHING;
INSERT INTO public.landing_pages(tenant_id,path,title,summary,sections,kind,image,faq,status,city,district,neighborhood,service,local_context,logistics,evidence,reviewed_at) SELECT id,'/rehber/tarama-verisinden-cad','Tarama verisinden CAD modeline','Nokta bulutu, yüzey ağı ve düzenlenebilir CAD çıktısını ayırarak tersine mühendislik talebinizi doğru kapsamlandırın. 3dsanayi: endüstriyel parça & fikstür odağında değerlendirme.','[{"title":"Endüstriyel parça & fikstür","body":"3dsanayi: İstanbul’da 3D baskı, 3D tarama ve 3D modelleme. Endüstriyel parça & fikstür için proje bazlı üretim. Projenizde 3D baskı, 3D tarama ve 3D modelleme adımlarından hangilerinin gerekli olduğunu kullanım amacınızla birlikte belirleyin."},{"title":"Hangi veri elinizde?","body":"Tarama sonucunuz nokta verisi veya üçgen yüzey ağı olabilir. Düzenlenebilir katı model gereksinimini ayrıca belirtin. Görüntülenebilen bir dosyanın otomatik olarak parametrik CAD dosyası olduğu varsayılmaz."},{"title":"Fonksiyonel yüzeyler","body":"Delik, mil yatağı, oturma yüzeyi ve bağlantı eksenlerini işaretleyin. Aşınmış veya kırılmış bölgeyi olduğu gibi kopyalamak yerine korunması gereken tasarım ilişkisini açıklayın. Gerekirse sağlam karşı parça da değerlendirmeye eklenir."},{"title":"Teslim ve kontrol","body":"İstenen formatı, revizyon kapsamını ve kontrol edilecek ölçüleri baştan belirleyin. Tarama ile CAD arasındaki farkların nasıl değerlendirileceğini kararlaştırın. Sadece görsel benzerlik, ölçüsel kabulün yerine geçmez."}]'::jsonb,'guide','/brand/industrial/fixture.webp','[{"q":"İlk değerlendirme için ne paylaşmalıyım?","a":"Tarama sonucunuz nokta verisi veya üçgen yüzey ağı olabilir. Düzenlenebilir katı model gereksinimini ayrıca belirtin. Görüntülenebilen bir dosyanın otomatik olarak parametrik CAD dosyası olduğu varsayılmaz."},{"q":"Talebe nasıl başlayabilirim?","a":"3D Studio üzerinden dosyanızı, adet ve kullanım koşullarınızı paylaşabilirsiniz. Dosyanız yoksa fotoğraf, ölçü ve beklenen çıktıyla modelleme değerlendirmesi isteyin."}]'::jsonb,'published','','','','','','','',NULL FROM public.tenants WHERE slug='3dsanayi' ON CONFLICT(tenant_id,path) DO NOTHING;
INSERT INTO public.landing_pages(tenant_id,path,title,summary,sections,kind,image,faq,status,city,district,neighborhood,service,local_context,logistics,evidence,reviewed_at) SELECT id,'/rehber/kesit-nasil-incelenir','3D modelde kesit nasıl incelenir?','Kesit düzlemini kullanarak iç boşlukları, montaj ilişkilerini ve beklenmeyen yüzeyleri görünür hale getirin. 3dsanayi: endüstriyel parça & fikstür odağında değerlendirme.','[{"title":"Endüstriyel parça & fikstür","body":"3dsanayi: İstanbul’da 3D baskı, 3D tarama ve 3D modelleme. Endüstriyel parça & fikstür için proje bazlı üretim. Projenizde 3D baskı, 3D tarama ve 3D modelleme adımlarından hangilerinin gerekli olduğunu kullanım amacınızla birlikte belirleyin."},{"title":"Düzlem yönünü seçin","body":"İncelemek istediğiniz detayın geçtiği ekseni bulun. X, Y ve Z yönlerini sırayla deneyin; sonra düzlemi yavaşça modelin içinden geçirin. Modeli döndürmek, birbirinin arkasında kalan yüzeyleri ayırt etmeye yardımcı olur."},{"title":"Görsel kesitin sınırları","body":"Tarayıcıdaki araç yüzeyleri düzleme göre gizler. Açılan kesiti kapatmaz, takım yolu veya baskı katmanı üretmez. Duvar kalınlığı ya da tolerans raporu gerekiyorsa ölçüm ve üretim yazılımlarındaki uygun araçlarla doğrulama yapın."},{"title":"Bulgunuzu tarif edin","body":"İncelediğiniz ekseni, düzlem konumunu ve sorunlu bölgeyi not edin. Talebe dosyanın aynı revizyonunu ekleyin. Bir ekran görüntüsünde görünen boşluğun tasarım amacı mı, dosya hatası mı olduğunu açıklamadan üretim kararı vermeyin."}]'::jsonb,'guide','/brand/industrial/fixture.webp','[{"q":"İlk değerlendirme için ne paylaşmalıyım?","a":"İncelemek istediğiniz detayın geçtiği ekseni bulun. X, Y ve Z yönlerini sırayla deneyin; sonra düzlemi yavaşça modelin içinden geçirin. Modeli döndürmek, birbirinin arkasında kalan yüzeyleri ayırt etmeye yardımcı olur."},{"q":"Talebe nasıl başlayabilirim?","a":"3D Studio üzerinden dosyanızı, adet ve kullanım koşullarınızı paylaşabilirsiniz. Dosyanız yoksa fotoğraf, ölçü ve beklenen çıktıyla modelleme değerlendirmesi isteyin."}]'::jsonb,'published','','','','','','','',NULL FROM public.tenants WHERE slug='3dsanayi' ON CONFLICT(tenant_id,path) DO NOTHING;
INSERT INTO public.landing_pages(tenant_id,path,title,summary,sections,kind,image,faq,status,city,district,neighborhood,service,local_context,logistics,evidence,reviewed_at) SELECT id,'/rehber/teknik-teklif-dosyasi','Teknik teklif dosyası nasıl hazırlanır?','Satın alma ve teknik ekiplerin aynı dosya üzerinden ilerlemesi için parça, adet, revizyon ve kabul bilgilerini düzenleyin. 3dsanayi: endüstriyel parça & fikstür odağında değerlendirme.','[{"title":"Endüstriyel parça & fikstür","body":"3dsanayi: İstanbul’da 3D baskı, 3D tarama ve 3D modelleme. Endüstriyel parça & fikstür için proje bazlı üretim. Projenizde 3D baskı, 3D tarama ve 3D modelleme adımlarından hangilerinin gerekli olduğunu kullanım amacınızla birlikte belirleyin."},{"title":"Tek bir parça tablosu","body":"Her satırda parça kodu, dosya adı, revizyon ve adet bulunsun. Alternatif tasarımları aynı satırda birleştirmeyin. Hangi parçaların birlikte monte edileceğini belirtin ve montaj çizimini ilişkilendirin."},{"title":"Kabul beklentisi","body":"Kritik ölçüler, görünür yüzeyler, işlevsel kontroller ve numune onayını kimin vereceği talepte yer alsın. Belgelenmeyen bir beklentinin teklif kapsamına otomatik girdiğini varsaymayın. Teslim dosyası ve fiziksel ürün kapsamını ayrı yazın."},{"title":"Takvim ve değişiklik","body":"Hedef tarihi, ara onay adımlarını ve revizyon için ayrılan süreyi belirtin. Talep sonrası geometri veya adet değişirse teklif yeniden değerlendirilebilir. Onaylanan sürümü teknik ekip ve satın alma arasında ortak referans yapın."}]'::jsonb,'guide','/brand/industrial/fixture.webp','[{"q":"İlk değerlendirme için ne paylaşmalıyım?","a":"Her satırda parça kodu, dosya adı, revizyon ve adet bulunsun. Alternatif tasarımları aynı satırda birleştirmeyin. Hangi parçaların birlikte monte edileceğini belirtin ve montaj çizimini ilişkilendirin."},{"q":"Talebe nasıl başlayabilirim?","a":"3D Studio üzerinden dosyanızı, adet ve kullanım koşullarınızı paylaşabilirsiniz. Dosyanız yoksa fotoğraf, ölçü ve beklenen çıktıyla modelleme değerlendirmesi isteyin."}]'::jsonb,'published','','','','','','','',NULL FROM public.tenants WHERE slug='3dsanayi' ON CONFLICT(tenant_id,path) DO NOTHING;
INSERT INTO public.landing_pages(tenant_id,path,title,summary,sections,kind,image,faq,status,city,district,neighborhood,service,local_context,logistics,evidence,reviewed_at) SELECT id,'/rehber/malzeme-secim-sorulari','Malzeme seçmeden önce sorulacak sorular','Malzeme kararını yalnızca isim veya renge göre değil, parçanın işlevi ve çalışma koşullarına göre hazırlayın. 3dsanayi: endüstriyel parça & fikstür odağında değerlendirme.','[{"title":"Endüstriyel parça & fikstür","body":"3dsanayi: İstanbul’da 3D baskı, 3D tarama ve 3D modelleme. Endüstriyel parça & fikstür için proje bazlı üretim. Projenizde 3D baskı, 3D tarama ve 3D modelleme adımlarından hangilerinin gerekli olduğunu kullanım amacınızla birlikte belirleyin."},{"title":"Ortamı tanımlayın","body":"Parça nerede çalışacak? Sıcaklık, güneş, nem ve kimyasal temas var mı? Sürekli yük mü taşıyacak, aralıklı darbe mi alacak? Bu sorulara sayısal bilgi verebiliyorsanız talebe ekleyin; bilinmeyen koşulları da açıkça yazın."},{"title":"Geometriyi birlikte düşünün","body":"İnce bağlantılar, esneyen tırnaklar ve büyük düz yüzeyler farklı tasarım değerlendirmeleri gerektirir. Malzeme, yönlendirme ve üretim yöntemi birlikte ele alınmalıdır. Sadece doluluk oranını artırmak her işlevsel problemi çözmez."},{"title":"Numuneyle karar verin","body":"Kritik kullanımlarda numuneyi hedef ortama uygun bir kontrol planıyla değerlendirin. Malzeme veri sayfasını, üretim ayarlarını ve test koşullarını birbirine karıştırmayın. Nihai kabul ölçütünü üretimden önce belirleyin."}]'::jsonb,'guide','/brand/industrial/fixture.webp','[{"q":"İlk değerlendirme için ne paylaşmalıyım?","a":"Parça nerede çalışacak? Sıcaklık, güneş, nem ve kimyasal temas var mı? Sürekli yük mü taşıyacak, aralıklı darbe mi alacak? Bu sorulara sayısal bilgi verebiliyorsanız talebe ekleyin; bilinmeyen koşulları da açıkça yazın."},{"q":"Talebe nasıl başlayabilirim?","a":"3D Studio üzerinden dosyanızı, adet ve kullanım koşullarınızı paylaşabilirsiniz. Dosyanız yoksa fotoğraf, ölçü ve beklenen çıktıyla modelleme değerlendirmesi isteyin."}]'::jsonb,'published','','','','','','','',NULL FROM public.tenants WHERE slug='3dsanayi' ON CONFLICT(tenant_id,path) DO NOTHING;
INSERT INTO public.landing_pages(tenant_id,path,title,summary,sections,kind,image,faq,status,city,district,neighborhood,service,local_context,logistics,evidence,reviewed_at) SELECT id,'/rehber/maket-olcek-planlama','Maket ölçeği ve parçalara ayırma','Mimari modelin fiziksel ölçüsünü, okunabilir detayını ve taşıma ihtiyacını tek üretim planında birleştirin. 3dsanayi: endüstriyel parça & fikstür odağında değerlendirme.','[{"title":"Endüstriyel parça & fikstür","body":"3dsanayi: İstanbul’da 3D baskı, 3D tarama ve 3D modelleme. Endüstriyel parça & fikstür için proje bazlı üretim. Projenizde 3D baskı, 3D tarama ve 3D modelleme adımlarından hangilerinin gerekli olduğunu kullanım amacınızla birlikte belirleyin."},{"title":"Ölçeği hesaplayın","body":"Gerçek boyutu ölçek paydasına bölerek maket boyutunu bulun. Örneğin 10 metrelik bir uzunluk 1:100 ölçekte 100 milimetredir. Kaynak dosyanın metre veya milimetre oluşunu ayrıca kontrol edin."},{"title":"Detay seviyesini seçin","body":"Pencere, korkuluk ve peyzaj gibi öğeleri her ölçekte aynı biçimde üretmek uygun olmayabilir. Anlatım açısından gerekli ayrıntıları listeleyin. Fiziksel sınırlar nedeniyle sadeleştirilecek bölgeler için dijital onay alın."},{"title":"Taşıma ve montaj","body":"Taban ölçüsü, birleşim yerleri ve sökülebilir parçaları kutulama planıyla birlikte değerlendirin. Parçaları kodlayın ve yerleşim şemasını saklayın. Sergileme sırasında sık taşınacak bir maket için servis erişimini de planlayın."}]'::jsonb,'guide','/brand/industrial/fixture.webp','[{"q":"İlk değerlendirme için ne paylaşmalıyım?","a":"Gerçek boyutu ölçek paydasına bölerek maket boyutunu bulun. Örneğin 10 metrelik bir uzunluk 1:100 ölçekte 100 milimetredir. Kaynak dosyanın metre veya milimetre oluşunu ayrıca kontrol edin."},{"q":"Talebe nasıl başlayabilirim?","a":"3D Studio üzerinden dosyanızı, adet ve kullanım koşullarınızı paylaşabilirsiniz. Dosyanız yoksa fotoğraf, ölçü ve beklenen çıktıyla modelleme değerlendirmesi isteyin."}]'::jsonb,'published','','','','','','','',NULL FROM public.tenants WHERE slug='3dsanayi' ON CONFLICT(tenant_id,path) DO NOTHING;
INSERT INTO public.landing_pages(tenant_id,path,title,summary,sections,kind,image,faq,status,city,district,neighborhood,service,local_context,logistics,evidence,reviewed_at) SELECT id,'/rehber/numune-kabul-plani','Numune kabul planı','Bir prototipin hangi koşullarda onaylanacağını üretimden önce tanımlayarak revizyon görüşmelerini somutlaştırın. 3dsanayi: endüstriyel parça & fikstür odağında değerlendirme.','[{"title":"Endüstriyel parça & fikstür","body":"3dsanayi: İstanbul’da 3D baskı, 3D tarama ve 3D modelleme. Endüstriyel parça & fikstür için proje bazlı üretim. Projenizde 3D baskı, 3D tarama ve 3D modelleme adımlarından hangilerinin gerekli olduğunu kullanım amacınızla birlikte belirleyin."},{"title":"Kontrol maddeleri","body":"Görünüş, montaj uyumu, ölçü ve işlevi ayrı maddeler halinde yazın. Her maddenin kontrol yöntemini ve karar verecek kişiyi belirleyin. Sadece fotoğraftan onaylanamayacak beklentileri fiziksel deneme aşamasına bırakın."},{"title":"Kayıt düzeni","body":"Numunenin dosya revizyonu, malzemesi, adedi ve test tarihi bir arada tutulmalıdır. Test sırasında yapılan elle düzeltmeler varsa bunları da kaydedin. Yeni baskıda aynı düzeltmenin yeniden gerekmemesi için dijital modele geri işleyin."},{"title":"Onaydan tekrar siparişe","body":"Hangi maddelerin geçtiğini ve hangilerinin açık kaldığını listeleyin. Koşullu onayı nihai onaydan ayırın. Tekrar sipariş verirken aynı revizyonu, değişen adetleri ve yeni kullanım koşullarını belirtin."}]'::jsonb,'guide','/brand/industrial/fixture.webp','[{"q":"İlk değerlendirme için ne paylaşmalıyım?","a":"Görünüş, montaj uyumu, ölçü ve işlevi ayrı maddeler halinde yazın. Her maddenin kontrol yöntemini ve karar verecek kişiyi belirleyin. Sadece fotoğraftan onaylanamayacak beklentileri fiziksel deneme aşamasına bırakın."},{"q":"Talebe nasıl başlayabilirim?","a":"3D Studio üzerinden dosyanızı, adet ve kullanım koşullarınızı paylaşabilirsiniz. Dosyanız yoksa fotoğraf, ölçü ve beklenen çıktıyla modelleme değerlendirmesi isteyin."}]'::jsonb,'published','','','','','','','',NULL FROM public.tenants WHERE slug='3dsanayi' ON CONFLICT(tenant_id,path) DO NOTHING;
INSERT INTO public.landing_pages(tenant_id,path,title,summary,sections,kind,image,faq,status,city,district,neighborhood,service,local_context,logistics,evidence,reviewed_at) SELECT id,'/cozumler/kurumsal-proje-yonetimi','Kurumsal proje ve tedarik süreci','Teknik ekip, satın alma ve üretim arasında dosya, onay ve tekrar sipariş akışını aynı proje kapsamına bağlayın. 3dsanayi: endüstriyel parça & fikstür odağında değerlendirme.','[{"title":"Endüstriyel parça & fikstür","body":"3dsanayi: İstanbul’da 3D baskı, 3D tarama ve 3D modelleme. Endüstriyel parça & fikstür için proje bazlı üretim. Projenizde 3D baskı, 3D tarama ve 3D modelleme adımlarından hangilerinin gerekli olduğunu kullanım amacınızla birlikte belirleyin."},{"title":"Talep ve kapsam","body":"Projenin kullanım amacını, parça listesini ve hedef tarihini paylaşın. Modelleme, tarama, üretim ve son işlem kalemlerini ayrı değerlendirin. Teklifte hangi dosya ve fiziksel çıktıların teslim edileceği açıkça belirtilmelidir."},{"title":"Numune ve revizyon","body":"İlk numunenin kabul maddelerini ve onay sorumlusunu belirleyin. Değişiklik taleplerini tek bir revizyon listesinde toplayın. Yeni geometri, adet veya teslim koşulu fiyat ve takvimin tekrar değerlendirilmesini gerektirebilir."},{"title":"Tekrar sipariş","body":"Onaylı dosyanın parça kodunu ve revizyonunu saklayın. Tekrar siparişte yalnızca eski fotoğraf yerine bu referansı kullanın. Çalışma ortamı veya kullanım amacı değiştiyse teknik değerlendirmeyi yenileyin."}]'::jsonb,'solution','/brand/industrial/fixture.webp','[{"q":"İlk değerlendirme için ne paylaşmalıyım?","a":"Projenin kullanım amacını, parça listesini ve hedef tarihini paylaşın. Modelleme, tarama, üretim ve son işlem kalemlerini ayrı değerlendirin. Teklifte hangi dosya ve fiziksel çıktıların teslim edileceği açıkça belirtilmelidir."},{"q":"Talebe nasıl başlayabilirim?","a":"3D Studio üzerinden dosyanızı, adet ve kullanım koşullarınızı paylaşabilirsiniz. Dosyanız yoksa fotoğraf, ölçü ve beklenen çıktıyla modelleme değerlendirmesi isteyin."}]'::jsonb,'published','','','','','','','',NULL FROM public.tenants WHERE slug='3dsanayi' ON CONFLICT(tenant_id,path) DO NOTHING;
INSERT INTO public.landing_pages(tenant_id,path,title,summary,sections,kind,image,faq,status,city,district,neighborhood,service,local_context,logistics,evidence,reviewed_at) SELECT id,'/sektorler/endustriyel','Endüstriyel üretim','Üretim hattındaki özel aparat, montaj yardımcısı ve düşük adetli parça ihtiyaçlarını aynı teknik briefte toplayın. maketyanımda: mimari maket & proje sunumu odağında değerlendirme.','[{"title":"Mimari maket & proje sunumu","body":"maketyanımda: İstanbul’da 3D baskı, 3D tarama ve 3D modelleme. Mimari maket & proje sunumu için proje bazlı üretim. Projenizde 3D baskı, 3D tarama ve 3D modelleme adımlarından hangilerinin gerekli olduğunu kullanım amacınızla birlikte belirleyin."},{"title":"Hattaki görevi tarif edin","body":"Parçanın hangi operasyonda kullanıldığını, operatörün nasıl tuttuğunu ve hangi yüzeylerin referans alındığını açıklayın. Çevrim sırasında oluşan yük, sıcaklık ve kimyasal temas bilgisi üretim kararının girdisidir. Mevcut çizim varsa kritik ölçüleri ayrı işaretleyin."},{"title":"Pilot parçadan onaylı revizyona","body":"İlk numuneyi gerçek montaj noktasında değerlendirecek kişiyi belirleyin. Uyum, erişim ve operatör kullanımı ayrı kontrol başlıkları olmalıdır. Numune üzerinde yapılan değişiklikleri çizim revizyonuna işleyin; seri talebi yalnızca onaylanan dosyaya bağlayın."},{"title":"Satın alma dosyası","body":"Talebe parça kodu, adet, malzeme beklentisi ve kabul ölçütlerini ekleyin. Birden fazla parçanın aynı siparişte değerlendirilmesi gerekiyorsa dosya adlarını adet tablosuyla eşleştirin. Tekrarlı siparişlerde önceki revizyon ve değişen koşulları belirtin."}]'::jsonb,'sector','/brand/industrial/architecture.webp','[{"q":"İlk değerlendirme için ne paylaşmalıyım?","a":"Parçanın hangi operasyonda kullanıldığını, operatörün nasıl tuttuğunu ve hangi yüzeylerin referans alındığını açıklayın. Çevrim sırasında oluşan yük, sıcaklık ve kimyasal temas bilgisi üretim kararının girdisidir. Mevcut çizim varsa kritik ölçüleri ayrı işaretleyin."},{"q":"Talebe nasıl başlayabilirim?","a":"3D Studio üzerinden dosyanızı, adet ve kullanım koşullarınızı paylaşabilirsiniz. Dosyanız yoksa fotoğraf, ölçü ve beklenen çıktıyla modelleme değerlendirmesi isteyin."}]'::jsonb,'published','','','','','','','',NULL FROM public.tenants WHERE slug='maketyanimda' ON CONFLICT(tenant_id,path) DO NOTHING;
INSERT INTO public.landing_pages(tenant_id,path,title,summary,sections,kind,image,faq,status,city,district,neighborhood,service,local_context,logistics,evidence,reviewed_at) SELECT id,'/sektorler/otomotiv','Otomotiv ve yedek parça','Trim, kapak, klips ve prototip parçalarında numuneden modele uzanan süreci kullanım koşullarıyla birlikte planlayın. maketyanımda: mimari maket & proje sunumu odağında değerlendirme.','[{"title":"Mimari maket & proje sunumu","body":"maketyanımda: İstanbul’da 3D baskı, 3D tarama ve 3D modelleme. Mimari maket & proje sunumu için proje bazlı üretim. Projenizde 3D baskı, 3D tarama ve 3D modelleme adımlarından hangilerinin gerekli olduğunu kullanım amacınızla birlikte belirleyin."},{"title":"Montaj ilişkisini koruyun","body":"Tek başına kırık parçanın fotoğrafı her zaman yeterli değildir. Parçanın takıldığı bölgeyi, sağlam eşini ve bağlantı elemanlarını da gösterin. Geçme yönü ve esnemesi gereken bölgeler işaretlenirse modelleme kapsamı daha doğru belirlenir."},{"title":"Ortam koşullarını paylaşın","body":"İç mekân, güneş gören bölge veya motor çevresi farklı koşullar taşır. Sıcaklık, titreşim, kimyasal temas ve beklenen kullanım ömrünü anlatın. Görünüş numunesi ile işlevsel kullanım parçasını aynı kabul kriteriyle değerlendirmeyin."},{"title":"Doğrulama kapsamı","body":"Emniyet açısından kritik bir parçanın yeniden üretilmesi ayrıca mühendislik doğrulaması gerektirir. Talepte parçanın görevini açıkça belirtin. Prototipin montaja oturması, tek başına güvenli kullanım onayı anlamına gelmez."}]'::jsonb,'sector','/brand/industrial/architecture.webp','[{"q":"İlk değerlendirme için ne paylaşmalıyım?","a":"Tek başına kırık parçanın fotoğrafı her zaman yeterli değildir. Parçanın takıldığı bölgeyi, sağlam eşini ve bağlantı elemanlarını da gösterin. Geçme yönü ve esnemesi gereken bölgeler işaretlenirse modelleme kapsamı daha doğru belirlenir."},{"q":"Talebe nasıl başlayabilirim?","a":"3D Studio üzerinden dosyanızı, adet ve kullanım koşullarınızı paylaşabilirsiniz. Dosyanız yoksa fotoğraf, ölçü ve beklenen çıktıyla modelleme değerlendirmesi isteyin."}]'::jsonb,'published','','','','','','','',NULL FROM public.tenants WHERE slug='maketyanimda' ON CONFLICT(tenant_id,path) DO NOTHING;
INSERT INTO public.landing_pages(tenant_id,path,title,summary,sections,kind,image,faq,status,city,district,neighborhood,service,local_context,logistics,evidence,reviewed_at) SELECT id,'/sektorler/mimari-tasarim','Mimari ve tasarım','Kütle, cephe ve yerleşim maketlerinde ölçeği, gösterilecek detayları ve taşıma planını üretimden önce netleştirin. maketyanımda: mimari maket & proje sunumu odağında değerlendirme.','[{"title":"Mimari maket & proje sunumu","body":"maketyanımda: İstanbul’da 3D baskı, 3D tarama ve 3D modelleme. Mimari maket & proje sunumu için proje bazlı üretim. Projenizde 3D baskı, 3D tarama ve 3D modelleme adımlarından hangilerinin gerekli olduğunu kullanım amacınızla birlikte belirleyin."},{"title":"Ölçekte okunabilirlik","body":"Kaynak modelin birimini, hedef maket ölçeğini ve bitmiş taban ölçüsünü paylaşın. Cephedeki çok küçük detayların fiziksel makette nasıl temsil edileceğini kararlaştırın. Peyzaj, kütle ve iç mekân farklı ayrıntı seviyelerinde ele alınabilir."},{"title":"Bölünebilir üretim","body":"Maketin sergileneceği alan ve taşınacağı kutu boyutu, parçalara ayırma kararını etkiler. Birleşim yerlerini görünür cephelerden uzaklaştırmak veya sökülebilir kütleler kullanmak tasarım aşamasında değerlendirilebilir. Aydınlatma ve kablo kanalları ayrıca belirtilmelidir."},{"title":"Sunum onayı","body":"Renk, yüzey, etiket ve taban beklentisini referanslarla anlatın. Önce dijital yerleşim, sonra kritik bir detayın numunesi üzerinden karar verin. Son teslimden önce parça listesi ve yerleşim şemasını birlikte kontrol edin."}]'::jsonb,'sector','/brand/industrial/architecture.webp','[{"q":"İlk değerlendirme için ne paylaşmalıyım?","a":"Kaynak modelin birimini, hedef maket ölçeğini ve bitmiş taban ölçüsünü paylaşın. Cephedeki çok küçük detayların fiziksel makette nasıl temsil edileceğini kararlaştırın. Peyzaj, kütle ve iç mekân farklı ayrıntı seviyelerinde ele alınabilir."},{"q":"Talebe nasıl başlayabilirim?","a":"3D Studio üzerinden dosyanızı, adet ve kullanım koşullarınızı paylaşabilirsiniz. Dosyanız yoksa fotoğraf, ölçü ve beklenen çıktıyla modelleme değerlendirmesi isteyin."}]'::jsonb,'published','','','','','','','',NULL FROM public.tenants WHERE slug='maketyanimda' ON CONFLICT(tenant_id,path) DO NOTHING;
INSERT INTO public.landing_pages(tenant_id,path,title,summary,sections,kind,image,faq,status,city,district,neighborhood,service,local_context,logistics,evidence,reviewed_at) SELECT id,'/sektorler/medikal','Medikal tasarım ve eğitim','Anlatım, eğitim ve tasarım değerlendirmesi için anatomik gösterim ve cihaz gövdesi prototiplerinin kapsamını belirleyin. maketyanımda: mimari maket & proje sunumu odağında değerlendirme.','[{"title":"Mimari maket & proje sunumu","body":"maketyanımda: İstanbul’da 3D baskı, 3D tarama ve 3D modelleme. Mimari maket & proje sunumu için proje bazlı üretim. Projenizde 3D baskı, 3D tarama ve 3D modelleme adımlarından hangilerinin gerekli olduğunu kullanım amacınızla birlikte belirleyin."},{"title":"Kullanım amacını ayırın","body":"Eğitimde gösterim, cihazın form kontrolü ve klinik kullanım birbirinden farklı kapsamlar taşır. Talebinizin hangi amaçla kullanılacağını açıkça yazın. Bu sayfadaki prototipleme yaklaşımı klinik uygunluk, sterilizasyon veya hasta temasına ilişkin bir onay değildir."},{"title":"Veri paylaşımı","body":"Gerekli dosya formatını ve görüntüleme beklentisini teknik ekiple belirleyin. Kişisel bilgi içeren görüntü veya dosyaları paylaşmadan önce yetki ve anonimleştirme süreçlerinizi tamamlayın. Teklif aşamasında mümkünse kimlik bilgisi içermeyen geometriyle başlayın."},{"title":"Eğitim modelinin kabulü","body":"Gösterilecek yapıları, renk ayrımını, sökülebilir bölümleri ve kullanılacak ölçeği listeleyin. Modelin anlatım amacına uygunluğunu konu uzmanı değerlendirmelidir. Dijital onay ile fiziksel yüzey beklentisini ayrı adımlarda ele alın."}]'::jsonb,'sector','/brand/industrial/architecture.webp','[{"q":"İlk değerlendirme için ne paylaşmalıyım?","a":"Eğitimde gösterim, cihazın form kontrolü ve klinik kullanım birbirinden farklı kapsamlar taşır. Talebinizin hangi amaçla kullanılacağını açıkça yazın. Bu sayfadaki prototipleme yaklaşımı klinik uygunluk, sterilizasyon veya hasta temasına ilişkin bir onay değildir."},{"q":"Talebe nasıl başlayabilirim?","a":"3D Studio üzerinden dosyanızı, adet ve kullanım koşullarınızı paylaşabilirsiniz. Dosyanız yoksa fotoğraf, ölçü ve beklenen çıktıyla modelleme değerlendirmesi isteyin."}]'::jsonb,'published','','','','','','','',NULL FROM public.tenants WHERE slug='maketyanimda' ON CONFLICT(tenant_id,path) DO NOTHING;
INSERT INTO public.landing_pages(tenant_id,path,title,summary,sections,kind,image,faq,status,city,district,neighborhood,service,local_context,logistics,evidence,reviewed_at) SELECT id,'/sektorler/savunma-havacilik','Havacılık ve teknik Ar-Ge','Form kontrolü, ergonomi ve montaj gösterimi için kullanılan teknik prototipleri izlenebilir bir dosya akışıyla planlayın. maketyanımda: mimari maket & proje sunumu odağında değerlendirme.','[{"title":"Mimari maket & proje sunumu","body":"maketyanımda: İstanbul’da 3D baskı, 3D tarama ve 3D modelleme. Mimari maket & proje sunumu için proje bazlı üretim. Projenizde 3D baskı, 3D tarama ve 3D modelleme adımlarından hangilerinin gerekli olduğunu kullanım amacınızla birlikte belirleyin."},{"title":"Kapsam ve veri sınırı","body":"Paylaşıma yetkili olduğunuz çizimleri ve kullanım amacı bilgisini talebe ekleyin. İlk değerlendirme için gerekli olmayan hassas proje detaylarını kapsam dışında tutun. Dosya erişimi, gizlilik ve revizyon sorumluları teklif öncesinde belirlenmelidir."},{"title":"Gösterim ve montaj prototipi","body":"Ergonomi maketi, bağlantı yerleşimi veya dış form numunesinde hangi kararın doğrulanacağını yazın. Görsel prototipin uçuşa elverişlilik veya işlevsel parça sertifikası sağlamadığını proje içinde açıkça ayırın. Kritik işlevler ayrı doğrulama planı gerektirir."},{"title":"İzlenebilir değerlendirme","body":"Dosya adı, parça kodu, revizyon, talep sahibi ve kabul kontrolünü ortak tabloda tutun. Fiziksel numune üzerindeki değişiklikleri dijital modele geri işleyin. Tekrar üretimde onaylı dosyanın aynı olduğundan emin olun."}]'::jsonb,'sector','/brand/industrial/architecture.webp','[{"q":"İlk değerlendirme için ne paylaşmalıyım?","a":"Paylaşıma yetkili olduğunuz çizimleri ve kullanım amacı bilgisini talebe ekleyin. İlk değerlendirme için gerekli olmayan hassas proje detaylarını kapsam dışında tutun. Dosya erişimi, gizlilik ve revizyon sorumluları teklif öncesinde belirlenmelidir."},{"q":"Talebe nasıl başlayabilirim?","a":"3D Studio üzerinden dosyanızı, adet ve kullanım koşullarınızı paylaşabilirsiniz. Dosyanız yoksa fotoğraf, ölçü ve beklenen çıktıyla modelleme değerlendirmesi isteyin."}]'::jsonb,'published','','','','','','','',NULL FROM public.tenants WHERE slug='maketyanimda' ON CONFLICT(tenant_id,path) DO NOTHING;
INSERT INTO public.landing_pages(tenant_id,path,title,summary,sections,kind,image,faq,status,city,district,neighborhood,service,local_context,logistics,evidence,reviewed_at) SELECT id,'/sektorler/egitim-arge','Eğitim ve Ar-Ge','Fikrinizi test edilebilir numunelere ayırın; bir sonraki tasarım kararını verecek prototipi üretin. maketyanımda: mimari maket & proje sunumu odağında değerlendirme.','[{"title":"Mimari maket & proje sunumu","body":"maketyanımda: İstanbul’da 3D baskı, 3D tarama ve 3D modelleme. Mimari maket & proje sunumu için proje bazlı üretim. Projenizde 3D baskı, 3D tarama ve 3D modelleme adımlarından hangilerinin gerekli olduğunu kullanım amacınızla birlikte belirleyin."},{"title":"Deneyi önce tanımlayın","body":"Bu numuneyle hangi soruya yanıt aradığınızı yazın. Form, mekanizma hareketi ve montaj uyumu farklı deneylerdir. Her birini aynı prototipte çözmeye çalışmak yerine karar sırasına göre ayırın."},{"title":"Revizyonları karşılaştırın","body":"Alternatifleri dosya adında işaretleyin; yalnızca değişen parametreleri bir tabloyla paylaşın. Deneme sonucunu not ederken kullanılan revizyonu ve test koşullarını ekleyin. Böylece yeni numunenin neden istendiği açık kalır."},{"title":"Bütçe ve adet","body":"Görünüş değerlendirmesi için gereken adetle kullanıcı testi için gereken adet aynı olmayabilir. Önce küçük bir doğrulama grubu planlayın. Malzeme, yüzey ve teslim tarihi seçimlerini deneyin amacıyla birlikte değerlendirin."}]'::jsonb,'sector','/brand/industrial/architecture.webp','[{"q":"İlk değerlendirme için ne paylaşmalıyım?","a":"Bu numuneyle hangi soruya yanıt aradığınızı yazın. Form, mekanizma hareketi ve montaj uyumu farklı deneylerdir. Her birini aynı prototipte çözmeye çalışmak yerine karar sırasına göre ayırın."},{"q":"Talebe nasıl başlayabilirim?","a":"3D Studio üzerinden dosyanızı, adet ve kullanım koşullarınızı paylaşabilirsiniz. Dosyanız yoksa fotoğraf, ölçü ve beklenen çıktıyla modelleme değerlendirmesi isteyin."}]'::jsonb,'published','','','','','','','',NULL FROM public.tenants WHERE slug='maketyanimda' ON CONFLICT(tenant_id,path) DO NOTHING;
INSERT INTO public.landing_pages(tenant_id,path,title,summary,sections,kind,image,faq,status,city,district,neighborhood,service,local_context,logistics,evidence,reviewed_at) SELECT id,'/sektorler/sanat-mucevher','Sanat, obje ve takı tasarımı','Heykel, obje ve takı tasarımlarında dijital formu fiziksel ölçekte görerek yüzey ve detay kararlarını geliştirin. maketyanımda: mimari maket & proje sunumu odağında değerlendirme.','[{"title":"Mimari maket & proje sunumu","body":"maketyanımda: İstanbul’da 3D baskı, 3D tarama ve 3D modelleme. Mimari maket & proje sunumu için proje bazlı üretim. Projenizde 3D baskı, 3D tarama ve 3D modelleme adımlarından hangilerinin gerekli olduğunu kullanım amacınızla birlikte belirleyin."},{"title":"Formun fiziksel etkisi","body":"Ekranda büyük görünen bir detay gerçek ölçekte kaybolabilir. Hedef ölçüyü, tutulacak yüzeyleri ve sergileme yönünü paylaşın. Organik modellerde yüzey sürekliliği ile bilinçli doku kararlarını ayırın."},{"title":"Son işlem planı","body":"Boyama, birleştirme veya başka bir üretim sürecine girdi oluşturma amacı varsa bunu baştan belirtin. Kalıp veya döküm sürecine uygunluk ilgili üretim yöntemiyle ayrıca değerlendirilmelidir. Her baskı malzemesinin her son işlemle uyumlu olduğu varsayılmaz."},{"title":"Tasarım hakları","body":"Üretim için ilettiğiniz modelin kullanım hakkının sizde olduğundan emin olun. Sanatçı adı, eser numarası ve revizyonu dosyada takip edin. Görsel sunum numunesi ile satışa çıkacak nihai ürünün kabul ölçütlerini ayrı belirleyin."}]'::jsonb,'sector','/brand/industrial/architecture.webp','[{"q":"İlk değerlendirme için ne paylaşmalıyım?","a":"Ekranda büyük görünen bir detay gerçek ölçekte kaybolabilir. Hedef ölçüyü, tutulacak yüzeyleri ve sergileme yönünü paylaşın. Organik modellerde yüzey sürekliliği ile bilinçli doku kararlarını ayırın."},{"q":"Talebe nasıl başlayabilirim?","a":"3D Studio üzerinden dosyanızı, adet ve kullanım koşullarınızı paylaşabilirsiniz. Dosyanız yoksa fotoğraf, ölçü ve beklenen çıktıyla modelleme değerlendirmesi isteyin."}]'::jsonb,'published','','','','','','','',NULL FROM public.tenants WHERE slug='maketyanimda' ON CONFLICT(tenant_id,path) DO NOTHING;
INSERT INTO public.landing_pages(tenant_id,path,title,summary,sections,kind,image,faq,status,city,district,neighborhood,service,local_context,logistics,evidence,reviewed_at) SELECT id,'/sektorler/drone-hobi','Drone, robotik ve hobi','Elektronik yerleşimi, kablo yönetimi ve montaj yardımcıları için modelleme ve prototip planınızı oluşturun. maketyanımda: mimari maket & proje sunumu odağında değerlendirme.','[{"title":"Mimari maket & proje sunumu","body":"maketyanımda: İstanbul’da 3D baskı, 3D tarama ve 3D modelleme. Mimari maket & proje sunumu için proje bazlı üretim. Projenizde 3D baskı, 3D tarama ve 3D modelleme adımlarından hangilerinin gerekli olduğunu kullanım amacınızla birlikte belirleyin."},{"title":"Bileşen yerleşimi","body":"Kart, sensör, bağlantı ve kablo ölçülerini aynı referans sisteminde paylaşın. Montaj sırasında alet erişimi ve kablo bükülme alanını da düşünün. Sadece dış ölçüleri vermek, parçanın sorunsuz monte edileceğini göstermez."},{"title":"Deneme koşulları","body":"Titreşim, dış ortam ve hareketli mekanizma ilişkisini belirtin. Uçuş veya yüksek hız gerektiren kullanımda parça doğrulaması ayrıca ele alınmalıdır. Tasarım numunesini doğrudan güvenlik açısından kritik kullanıma uygun kabul etmeyin."},{"title":"Onarım ve değiştirme","body":"Sık sökülecek kapakları, tüketilecek parçaları ve farklı sürümlerde değişecek bağlantıları işaretleyin. Tasarımın servis kolaylığı prototip üzerinden kontrol edilebilir. Sonraki sipariş için onaylanan dosyayı ve bağlantı ölçülerini saklayın."}]'::jsonb,'sector','/brand/industrial/architecture.webp','[{"q":"İlk değerlendirme için ne paylaşmalıyım?","a":"Kart, sensör, bağlantı ve kablo ölçülerini aynı referans sisteminde paylaşın. Montaj sırasında alet erişimi ve kablo bükülme alanını da düşünün. Sadece dış ölçüleri vermek, parçanın sorunsuz monte edileceğini göstermez."},{"q":"Talebe nasıl başlayabilirim?","a":"3D Studio üzerinden dosyanızı, adet ve kullanım koşullarınızı paylaşabilirsiniz. Dosyanız yoksa fotoğraf, ölçü ve beklenen çıktıyla modelleme değerlendirmesi isteyin."}]'::jsonb,'published','','','','','','','',NULL FROM public.tenants WHERE slug='maketyanimda' ON CONFLICT(tenant_id,path) DO NOTHING;
INSERT INTO public.landing_pages(tenant_id,path,title,summary,sections,kind,image,faq,status,city,district,neighborhood,service,local_context,logistics,evidence,reviewed_at) SELECT id,'/rehber/stl-dosya-hazirlama','STL dosyası hazırlama kontrol listesi','Tekliften önce birim, dış ölçü, yüzey bütünlüğü ve revizyon bilgisini aynı kontrol listesiyle gözden geçirin. maketyanımda: mimari maket & proje sunumu odağında değerlendirme.','[{"title":"Mimari maket & proje sunumu","body":"maketyanımda: İstanbul’da 3D baskı, 3D tarama ve 3D modelleme. Mimari maket & proje sunumu için proje bazlı üretim. Projenizde 3D baskı, 3D tarama ve 3D modelleme adımlarından hangilerinin gerekli olduğunu kullanım amacınızla birlikte belirleyin."},{"title":"Birim ve ölçek","body":"STL dosyasındaki koordinatları hangi birimde dışa aktardığınızı kaydedin. Önizleyicide dış ölçüleri tasarımınızla karşılaştırın. Milimetre ve inç karışıklığı, görünüş aynı olsa da üretilecek parçanın boyutunu değiştirir."},{"title":"Yüzey ve ayrıntı","body":"Modelde açık yüzey, üst üste geometri veya istenmeyen iç parçalar olup olmadığını CAD yazılımınızda kontrol edin. Görüntüleyicide kesit almak iç ilişkileri anlamayı kolaylaştırır; ancak otomatik üretilebilirlik doğrulamasının yerini tutmaz."},{"title":"Dosya paketi","body":"Parça kodu ve revizyonu dosya adına ekleyin. Adet, kritik ölçü ve kullanım koşullarını ayrı not edin. Birden fazla dosyada aynı kodu farklı revizyonlarla karıştırmayın; onaylanmış sürümü açıkça işaretleyin."}]'::jsonb,'guide','/brand/industrial/architecture.webp','[{"q":"İlk değerlendirme için ne paylaşmalıyım?","a":"STL dosyasındaki koordinatları hangi birimde dışa aktardığınızı kaydedin. Önizleyicide dış ölçüleri tasarımınızla karşılaştırın. Milimetre ve inç karışıklığı, görünüş aynı olsa da üretilecek parçanın boyutunu değiştirir."},{"q":"Talebe nasıl başlayabilirim?","a":"3D Studio üzerinden dosyanızı, adet ve kullanım koşullarınızı paylaşabilirsiniz. Dosyanız yoksa fotoğraf, ölçü ve beklenen çıktıyla modelleme değerlendirmesi isteyin."}]'::jsonb,'published','','','','','','','',NULL FROM public.tenants WHERE slug='maketyanimda' ON CONFLICT(tenant_id,path) DO NOTHING;
INSERT INTO public.landing_pages(tenant_id,path,title,summary,sections,kind,image,faq,status,city,district,neighborhood,service,local_context,logistics,evidence,reviewed_at) SELECT id,'/rehber/tarama-verisinden-cad','Tarama verisinden CAD modeline','Nokta bulutu, yüzey ağı ve düzenlenebilir CAD çıktısını ayırarak tersine mühendislik talebinizi doğru kapsamlandırın. maketyanımda: mimari maket & proje sunumu odağında değerlendirme.','[{"title":"Mimari maket & proje sunumu","body":"maketyanımda: İstanbul’da 3D baskı, 3D tarama ve 3D modelleme. Mimari maket & proje sunumu için proje bazlı üretim. Projenizde 3D baskı, 3D tarama ve 3D modelleme adımlarından hangilerinin gerekli olduğunu kullanım amacınızla birlikte belirleyin."},{"title":"Hangi veri elinizde?","body":"Tarama sonucunuz nokta verisi veya üçgen yüzey ağı olabilir. Düzenlenebilir katı model gereksinimini ayrıca belirtin. Görüntülenebilen bir dosyanın otomatik olarak parametrik CAD dosyası olduğu varsayılmaz."},{"title":"Fonksiyonel yüzeyler","body":"Delik, mil yatağı, oturma yüzeyi ve bağlantı eksenlerini işaretleyin. Aşınmış veya kırılmış bölgeyi olduğu gibi kopyalamak yerine korunması gereken tasarım ilişkisini açıklayın. Gerekirse sağlam karşı parça da değerlendirmeye eklenir."},{"title":"Teslim ve kontrol","body":"İstenen formatı, revizyon kapsamını ve kontrol edilecek ölçüleri baştan belirleyin. Tarama ile CAD arasındaki farkların nasıl değerlendirileceğini kararlaştırın. Sadece görsel benzerlik, ölçüsel kabulün yerine geçmez."}]'::jsonb,'guide','/brand/industrial/architecture.webp','[{"q":"İlk değerlendirme için ne paylaşmalıyım?","a":"Tarama sonucunuz nokta verisi veya üçgen yüzey ağı olabilir. Düzenlenebilir katı model gereksinimini ayrıca belirtin. Görüntülenebilen bir dosyanın otomatik olarak parametrik CAD dosyası olduğu varsayılmaz."},{"q":"Talebe nasıl başlayabilirim?","a":"3D Studio üzerinden dosyanızı, adet ve kullanım koşullarınızı paylaşabilirsiniz. Dosyanız yoksa fotoğraf, ölçü ve beklenen çıktıyla modelleme değerlendirmesi isteyin."}]'::jsonb,'published','','','','','','','',NULL FROM public.tenants WHERE slug='maketyanimda' ON CONFLICT(tenant_id,path) DO NOTHING;
INSERT INTO public.landing_pages(tenant_id,path,title,summary,sections,kind,image,faq,status,city,district,neighborhood,service,local_context,logistics,evidence,reviewed_at) SELECT id,'/rehber/kesit-nasil-incelenir','3D modelde kesit nasıl incelenir?','Kesit düzlemini kullanarak iç boşlukları, montaj ilişkilerini ve beklenmeyen yüzeyleri görünür hale getirin. maketyanımda: mimari maket & proje sunumu odağında değerlendirme.','[{"title":"Mimari maket & proje sunumu","body":"maketyanımda: İstanbul’da 3D baskı, 3D tarama ve 3D modelleme. Mimari maket & proje sunumu için proje bazlı üretim. Projenizde 3D baskı, 3D tarama ve 3D modelleme adımlarından hangilerinin gerekli olduğunu kullanım amacınızla birlikte belirleyin."},{"title":"Düzlem yönünü seçin","body":"İncelemek istediğiniz detayın geçtiği ekseni bulun. X, Y ve Z yönlerini sırayla deneyin; sonra düzlemi yavaşça modelin içinden geçirin. Modeli döndürmek, birbirinin arkasında kalan yüzeyleri ayırt etmeye yardımcı olur."},{"title":"Görsel kesitin sınırları","body":"Tarayıcıdaki araç yüzeyleri düzleme göre gizler. Açılan kesiti kapatmaz, takım yolu veya baskı katmanı üretmez. Duvar kalınlığı ya da tolerans raporu gerekiyorsa ölçüm ve üretim yazılımlarındaki uygun araçlarla doğrulama yapın."},{"title":"Bulgunuzu tarif edin","body":"İncelediğiniz ekseni, düzlem konumunu ve sorunlu bölgeyi not edin. Talebe dosyanın aynı revizyonunu ekleyin. Bir ekran görüntüsünde görünen boşluğun tasarım amacı mı, dosya hatası mı olduğunu açıklamadan üretim kararı vermeyin."}]'::jsonb,'guide','/brand/industrial/architecture.webp','[{"q":"İlk değerlendirme için ne paylaşmalıyım?","a":"İncelemek istediğiniz detayın geçtiği ekseni bulun. X, Y ve Z yönlerini sırayla deneyin; sonra düzlemi yavaşça modelin içinden geçirin. Modeli döndürmek, birbirinin arkasında kalan yüzeyleri ayırt etmeye yardımcı olur."},{"q":"Talebe nasıl başlayabilirim?","a":"3D Studio üzerinden dosyanızı, adet ve kullanım koşullarınızı paylaşabilirsiniz. Dosyanız yoksa fotoğraf, ölçü ve beklenen çıktıyla modelleme değerlendirmesi isteyin."}]'::jsonb,'published','','','','','','','',NULL FROM public.tenants WHERE slug='maketyanimda' ON CONFLICT(tenant_id,path) DO NOTHING;
INSERT INTO public.landing_pages(tenant_id,path,title,summary,sections,kind,image,faq,status,city,district,neighborhood,service,local_context,logistics,evidence,reviewed_at) SELECT id,'/rehber/teknik-teklif-dosyasi','Teknik teklif dosyası nasıl hazırlanır?','Satın alma ve teknik ekiplerin aynı dosya üzerinden ilerlemesi için parça, adet, revizyon ve kabul bilgilerini düzenleyin. maketyanımda: mimari maket & proje sunumu odağında değerlendirme.','[{"title":"Mimari maket & proje sunumu","body":"maketyanımda: İstanbul’da 3D baskı, 3D tarama ve 3D modelleme. Mimari maket & proje sunumu için proje bazlı üretim. Projenizde 3D baskı, 3D tarama ve 3D modelleme adımlarından hangilerinin gerekli olduğunu kullanım amacınızla birlikte belirleyin."},{"title":"Tek bir parça tablosu","body":"Her satırda parça kodu, dosya adı, revizyon ve adet bulunsun. Alternatif tasarımları aynı satırda birleştirmeyin. Hangi parçaların birlikte monte edileceğini belirtin ve montaj çizimini ilişkilendirin."},{"title":"Kabul beklentisi","body":"Kritik ölçüler, görünür yüzeyler, işlevsel kontroller ve numune onayını kimin vereceği talepte yer alsın. Belgelenmeyen bir beklentinin teklif kapsamına otomatik girdiğini varsaymayın. Teslim dosyası ve fiziksel ürün kapsamını ayrı yazın."},{"title":"Takvim ve değişiklik","body":"Hedef tarihi, ara onay adımlarını ve revizyon için ayrılan süreyi belirtin. Talep sonrası geometri veya adet değişirse teklif yeniden değerlendirilebilir. Onaylanan sürümü teknik ekip ve satın alma arasında ortak referans yapın."}]'::jsonb,'guide','/brand/industrial/architecture.webp','[{"q":"İlk değerlendirme için ne paylaşmalıyım?","a":"Her satırda parça kodu, dosya adı, revizyon ve adet bulunsun. Alternatif tasarımları aynı satırda birleştirmeyin. Hangi parçaların birlikte monte edileceğini belirtin ve montaj çizimini ilişkilendirin."},{"q":"Talebe nasıl başlayabilirim?","a":"3D Studio üzerinden dosyanızı, adet ve kullanım koşullarınızı paylaşabilirsiniz. Dosyanız yoksa fotoğraf, ölçü ve beklenen çıktıyla modelleme değerlendirmesi isteyin."}]'::jsonb,'published','','','','','','','',NULL FROM public.tenants WHERE slug='maketyanimda' ON CONFLICT(tenant_id,path) DO NOTHING;
INSERT INTO public.landing_pages(tenant_id,path,title,summary,sections,kind,image,faq,status,city,district,neighborhood,service,local_context,logistics,evidence,reviewed_at) SELECT id,'/rehber/malzeme-secim-sorulari','Malzeme seçmeden önce sorulacak sorular','Malzeme kararını yalnızca isim veya renge göre değil, parçanın işlevi ve çalışma koşullarına göre hazırlayın. maketyanımda: mimari maket & proje sunumu odağında değerlendirme.','[{"title":"Mimari maket & proje sunumu","body":"maketyanımda: İstanbul’da 3D baskı, 3D tarama ve 3D modelleme. Mimari maket & proje sunumu için proje bazlı üretim. Projenizde 3D baskı, 3D tarama ve 3D modelleme adımlarından hangilerinin gerekli olduğunu kullanım amacınızla birlikte belirleyin."},{"title":"Ortamı tanımlayın","body":"Parça nerede çalışacak? Sıcaklık, güneş, nem ve kimyasal temas var mı? Sürekli yük mü taşıyacak, aralıklı darbe mi alacak? Bu sorulara sayısal bilgi verebiliyorsanız talebe ekleyin; bilinmeyen koşulları da açıkça yazın."},{"title":"Geometriyi birlikte düşünün","body":"İnce bağlantılar, esneyen tırnaklar ve büyük düz yüzeyler farklı tasarım değerlendirmeleri gerektirir. Malzeme, yönlendirme ve üretim yöntemi birlikte ele alınmalıdır. Sadece doluluk oranını artırmak her işlevsel problemi çözmez."},{"title":"Numuneyle karar verin","body":"Kritik kullanımlarda numuneyi hedef ortama uygun bir kontrol planıyla değerlendirin. Malzeme veri sayfasını, üretim ayarlarını ve test koşullarını birbirine karıştırmayın. Nihai kabul ölçütünü üretimden önce belirleyin."}]'::jsonb,'guide','/brand/industrial/architecture.webp','[{"q":"İlk değerlendirme için ne paylaşmalıyım?","a":"Parça nerede çalışacak? Sıcaklık, güneş, nem ve kimyasal temas var mı? Sürekli yük mü taşıyacak, aralıklı darbe mi alacak? Bu sorulara sayısal bilgi verebiliyorsanız talebe ekleyin; bilinmeyen koşulları da açıkça yazın."},{"q":"Talebe nasıl başlayabilirim?","a":"3D Studio üzerinden dosyanızı, adet ve kullanım koşullarınızı paylaşabilirsiniz. Dosyanız yoksa fotoğraf, ölçü ve beklenen çıktıyla modelleme değerlendirmesi isteyin."}]'::jsonb,'published','','','','','','','',NULL FROM public.tenants WHERE slug='maketyanimda' ON CONFLICT(tenant_id,path) DO NOTHING;
INSERT INTO public.landing_pages(tenant_id,path,title,summary,sections,kind,image,faq,status,city,district,neighborhood,service,local_context,logistics,evidence,reviewed_at) SELECT id,'/rehber/maket-olcek-planlama','Maket ölçeği ve parçalara ayırma','Mimari modelin fiziksel ölçüsünü, okunabilir detayını ve taşıma ihtiyacını tek üretim planında birleştirin. maketyanımda: mimari maket & proje sunumu odağında değerlendirme.','[{"title":"Mimari maket & proje sunumu","body":"maketyanımda: İstanbul’da 3D baskı, 3D tarama ve 3D modelleme. Mimari maket & proje sunumu için proje bazlı üretim. Projenizde 3D baskı, 3D tarama ve 3D modelleme adımlarından hangilerinin gerekli olduğunu kullanım amacınızla birlikte belirleyin."},{"title":"Ölçeği hesaplayın","body":"Gerçek boyutu ölçek paydasına bölerek maket boyutunu bulun. Örneğin 10 metrelik bir uzunluk 1:100 ölçekte 100 milimetredir. Kaynak dosyanın metre veya milimetre oluşunu ayrıca kontrol edin."},{"title":"Detay seviyesini seçin","body":"Pencere, korkuluk ve peyzaj gibi öğeleri her ölçekte aynı biçimde üretmek uygun olmayabilir. Anlatım açısından gerekli ayrıntıları listeleyin. Fiziksel sınırlar nedeniyle sadeleştirilecek bölgeler için dijital onay alın."},{"title":"Taşıma ve montaj","body":"Taban ölçüsü, birleşim yerleri ve sökülebilir parçaları kutulama planıyla birlikte değerlendirin. Parçaları kodlayın ve yerleşim şemasını saklayın. Sergileme sırasında sık taşınacak bir maket için servis erişimini de planlayın."}]'::jsonb,'guide','/brand/industrial/architecture.webp','[{"q":"İlk değerlendirme için ne paylaşmalıyım?","a":"Gerçek boyutu ölçek paydasına bölerek maket boyutunu bulun. Örneğin 10 metrelik bir uzunluk 1:100 ölçekte 100 milimetredir. Kaynak dosyanın metre veya milimetre oluşunu ayrıca kontrol edin."},{"q":"Talebe nasıl başlayabilirim?","a":"3D Studio üzerinden dosyanızı, adet ve kullanım koşullarınızı paylaşabilirsiniz. Dosyanız yoksa fotoğraf, ölçü ve beklenen çıktıyla modelleme değerlendirmesi isteyin."}]'::jsonb,'published','','','','','','','',NULL FROM public.tenants WHERE slug='maketyanimda' ON CONFLICT(tenant_id,path) DO NOTHING;
INSERT INTO public.landing_pages(tenant_id,path,title,summary,sections,kind,image,faq,status,city,district,neighborhood,service,local_context,logistics,evidence,reviewed_at) SELECT id,'/rehber/numune-kabul-plani','Numune kabul planı','Bir prototipin hangi koşullarda onaylanacağını üretimden önce tanımlayarak revizyon görüşmelerini somutlaştırın. maketyanımda: mimari maket & proje sunumu odağında değerlendirme.','[{"title":"Mimari maket & proje sunumu","body":"maketyanımda: İstanbul’da 3D baskı, 3D tarama ve 3D modelleme. Mimari maket & proje sunumu için proje bazlı üretim. Projenizde 3D baskı, 3D tarama ve 3D modelleme adımlarından hangilerinin gerekli olduğunu kullanım amacınızla birlikte belirleyin."},{"title":"Kontrol maddeleri","body":"Görünüş, montaj uyumu, ölçü ve işlevi ayrı maddeler halinde yazın. Her maddenin kontrol yöntemini ve karar verecek kişiyi belirleyin. Sadece fotoğraftan onaylanamayacak beklentileri fiziksel deneme aşamasına bırakın."},{"title":"Kayıt düzeni","body":"Numunenin dosya revizyonu, malzemesi, adedi ve test tarihi bir arada tutulmalıdır. Test sırasında yapılan elle düzeltmeler varsa bunları da kaydedin. Yeni baskıda aynı düzeltmenin yeniden gerekmemesi için dijital modele geri işleyin."},{"title":"Onaydan tekrar siparişe","body":"Hangi maddelerin geçtiğini ve hangilerinin açık kaldığını listeleyin. Koşullu onayı nihai onaydan ayırın. Tekrar sipariş verirken aynı revizyonu, değişen adetleri ve yeni kullanım koşullarını belirtin."}]'::jsonb,'guide','/brand/industrial/architecture.webp','[{"q":"İlk değerlendirme için ne paylaşmalıyım?","a":"Görünüş, montaj uyumu, ölçü ve işlevi ayrı maddeler halinde yazın. Her maddenin kontrol yöntemini ve karar verecek kişiyi belirleyin. Sadece fotoğraftan onaylanamayacak beklentileri fiziksel deneme aşamasına bırakın."},{"q":"Talebe nasıl başlayabilirim?","a":"3D Studio üzerinden dosyanızı, adet ve kullanım koşullarınızı paylaşabilirsiniz. Dosyanız yoksa fotoğraf, ölçü ve beklenen çıktıyla modelleme değerlendirmesi isteyin."}]'::jsonb,'published','','','','','','','',NULL FROM public.tenants WHERE slug='maketyanimda' ON CONFLICT(tenant_id,path) DO NOTHING;
INSERT INTO public.landing_pages(tenant_id,path,title,summary,sections,kind,image,faq,status,city,district,neighborhood,service,local_context,logistics,evidence,reviewed_at) SELECT id,'/cozumler/kurumsal-proje-yonetimi','Kurumsal proje ve tedarik süreci','Teknik ekip, satın alma ve üretim arasında dosya, onay ve tekrar sipariş akışını aynı proje kapsamına bağlayın. maketyanımda: mimari maket & proje sunumu odağında değerlendirme.','[{"title":"Mimari maket & proje sunumu","body":"maketyanımda: İstanbul’da 3D baskı, 3D tarama ve 3D modelleme. Mimari maket & proje sunumu için proje bazlı üretim. Projenizde 3D baskı, 3D tarama ve 3D modelleme adımlarından hangilerinin gerekli olduğunu kullanım amacınızla birlikte belirleyin."},{"title":"Talep ve kapsam","body":"Projenin kullanım amacını, parça listesini ve hedef tarihini paylaşın. Modelleme, tarama, üretim ve son işlem kalemlerini ayrı değerlendirin. Teklifte hangi dosya ve fiziksel çıktıların teslim edileceği açıkça belirtilmelidir."},{"title":"Numune ve revizyon","body":"İlk numunenin kabul maddelerini ve onay sorumlusunu belirleyin. Değişiklik taleplerini tek bir revizyon listesinde toplayın. Yeni geometri, adet veya teslim koşulu fiyat ve takvimin tekrar değerlendirilmesini gerektirebilir."},{"title":"Tekrar sipariş","body":"Onaylı dosyanın parça kodunu ve revizyonunu saklayın. Tekrar siparişte yalnızca eski fotoğraf yerine bu referansı kullanın. Çalışma ortamı veya kullanım amacı değiştiyse teknik değerlendirmeyi yenileyin."}]'::jsonb,'solution','/brand/industrial/architecture.webp','[{"q":"İlk değerlendirme için ne paylaşmalıyım?","a":"Projenin kullanım amacını, parça listesini ve hedef tarihini paylaşın. Modelleme, tarama, üretim ve son işlem kalemlerini ayrı değerlendirin. Teklifte hangi dosya ve fiziksel çıktıların teslim edileceği açıkça belirtilmelidir."},{"q":"Talebe nasıl başlayabilirim?","a":"3D Studio üzerinden dosyanızı, adet ve kullanım koşullarınızı paylaşabilirsiniz. Dosyanız yoksa fotoğraf, ölçü ve beklenen çıktıyla modelleme değerlendirmesi isteyin."}]'::jsonb,'published','','','','','','','',NULL FROM public.tenants WHERE slug='maketyanimda' ON CONFLICT(tenant_id,path) DO NOTHING;
INSERT INTO public.landing_pages(tenant_id,path,title,summary,sections,kind,image,faq,status,city,district,neighborhood,service,local_context,logistics,evidence,reviewed_at) SELECT id,'/sektorler/endustriyel','Endüstriyel üretim','Üretim hattındaki özel aparat, montaj yardımcısı ve düşük adetli parça ihtiyaçlarını aynı teknik briefte toplayın. parçayanımda: özel plastik parça & otomotiv odağında değerlendirme.','[{"title":"Özel plastik parça & otomotiv","body":"parçayanımda: İstanbul’da 3D baskı, 3D tarama ve 3D modelleme. Özel plastik parça & otomotiv için proje bazlı üretim. Projenizde 3D baskı, 3D tarama ve 3D modelleme adımlarından hangilerinin gerekli olduğunu kullanım amacınızla birlikte belirleyin."},{"title":"Hattaki görevi tarif edin","body":"Parçanın hangi operasyonda kullanıldığını, operatörün nasıl tuttuğunu ve hangi yüzeylerin referans alındığını açıklayın. Çevrim sırasında oluşan yük, sıcaklık ve kimyasal temas bilgisi üretim kararının girdisidir. Mevcut çizim varsa kritik ölçüleri ayrı işaretleyin."},{"title":"Pilot parçadan onaylı revizyona","body":"İlk numuneyi gerçek montaj noktasında değerlendirecek kişiyi belirleyin. Uyum, erişim ve operatör kullanımı ayrı kontrol başlıkları olmalıdır. Numune üzerinde yapılan değişiklikleri çizim revizyonuna işleyin; seri talebi yalnızca onaylanan dosyaya bağlayın."},{"title":"Satın alma dosyası","body":"Talebe parça kodu, adet, malzeme beklentisi ve kabul ölçütlerini ekleyin. Birden fazla parçanın aynı siparişte değerlendirilmesi gerekiyorsa dosya adlarını adet tablosuyla eşleştirin. Tekrarlı siparişlerde önceki revizyon ve değişen koşulları belirtin."}]'::jsonb,'sector','/brand/industrial/parts.webp','[{"q":"İlk değerlendirme için ne paylaşmalıyım?","a":"Parçanın hangi operasyonda kullanıldığını, operatörün nasıl tuttuğunu ve hangi yüzeylerin referans alındığını açıklayın. Çevrim sırasında oluşan yük, sıcaklık ve kimyasal temas bilgisi üretim kararının girdisidir. Mevcut çizim varsa kritik ölçüleri ayrı işaretleyin."},{"q":"Talebe nasıl başlayabilirim?","a":"3D Studio üzerinden dosyanızı, adet ve kullanım koşullarınızı paylaşabilirsiniz. Dosyanız yoksa fotoğraf, ölçü ve beklenen çıktıyla modelleme değerlendirmesi isteyin."}]'::jsonb,'published','','','','','','','',NULL FROM public.tenants WHERE slug='parcayanimda' ON CONFLICT(tenant_id,path) DO NOTHING;
INSERT INTO public.landing_pages(tenant_id,path,title,summary,sections,kind,image,faq,status,city,district,neighborhood,service,local_context,logistics,evidence,reviewed_at) SELECT id,'/sektorler/otomotiv','Otomotiv ve yedek parça','Trim, kapak, klips ve prototip parçalarında numuneden modele uzanan süreci kullanım koşullarıyla birlikte planlayın. parçayanımda: özel plastik parça & otomotiv odağında değerlendirme.','[{"title":"Özel plastik parça & otomotiv","body":"parçayanımda: İstanbul’da 3D baskı, 3D tarama ve 3D modelleme. Özel plastik parça & otomotiv için proje bazlı üretim. Projenizde 3D baskı, 3D tarama ve 3D modelleme adımlarından hangilerinin gerekli olduğunu kullanım amacınızla birlikte belirleyin."},{"title":"Montaj ilişkisini koruyun","body":"Tek başına kırık parçanın fotoğrafı her zaman yeterli değildir. Parçanın takıldığı bölgeyi, sağlam eşini ve bağlantı elemanlarını da gösterin. Geçme yönü ve esnemesi gereken bölgeler işaretlenirse modelleme kapsamı daha doğru belirlenir."},{"title":"Ortam koşullarını paylaşın","body":"İç mekân, güneş gören bölge veya motor çevresi farklı koşullar taşır. Sıcaklık, titreşim, kimyasal temas ve beklenen kullanım ömrünü anlatın. Görünüş numunesi ile işlevsel kullanım parçasını aynı kabul kriteriyle değerlendirmeyin."},{"title":"Doğrulama kapsamı","body":"Emniyet açısından kritik bir parçanın yeniden üretilmesi ayrıca mühendislik doğrulaması gerektirir. Talepte parçanın görevini açıkça belirtin. Prototipin montaja oturması, tek başına güvenli kullanım onayı anlamına gelmez."}]'::jsonb,'sector','/brand/industrial/parts.webp','[{"q":"İlk değerlendirme için ne paylaşmalıyım?","a":"Tek başına kırık parçanın fotoğrafı her zaman yeterli değildir. Parçanın takıldığı bölgeyi, sağlam eşini ve bağlantı elemanlarını da gösterin. Geçme yönü ve esnemesi gereken bölgeler işaretlenirse modelleme kapsamı daha doğru belirlenir."},{"q":"Talebe nasıl başlayabilirim?","a":"3D Studio üzerinden dosyanızı, adet ve kullanım koşullarınızı paylaşabilirsiniz. Dosyanız yoksa fotoğraf, ölçü ve beklenen çıktıyla modelleme değerlendirmesi isteyin."}]'::jsonb,'published','','','','','','','',NULL FROM public.tenants WHERE slug='parcayanimda' ON CONFLICT(tenant_id,path) DO NOTHING;
INSERT INTO public.landing_pages(tenant_id,path,title,summary,sections,kind,image,faq,status,city,district,neighborhood,service,local_context,logistics,evidence,reviewed_at) SELECT id,'/sektorler/mimari-tasarim','Mimari ve tasarım','Kütle, cephe ve yerleşim maketlerinde ölçeği, gösterilecek detayları ve taşıma planını üretimden önce netleştirin. parçayanımda: özel plastik parça & otomotiv odağında değerlendirme.','[{"title":"Özel plastik parça & otomotiv","body":"parçayanımda: İstanbul’da 3D baskı, 3D tarama ve 3D modelleme. Özel plastik parça & otomotiv için proje bazlı üretim. Projenizde 3D baskı, 3D tarama ve 3D modelleme adımlarından hangilerinin gerekli olduğunu kullanım amacınızla birlikte belirleyin."},{"title":"Ölçekte okunabilirlik","body":"Kaynak modelin birimini, hedef maket ölçeğini ve bitmiş taban ölçüsünü paylaşın. Cephedeki çok küçük detayların fiziksel makette nasıl temsil edileceğini kararlaştırın. Peyzaj, kütle ve iç mekân farklı ayrıntı seviyelerinde ele alınabilir."},{"title":"Bölünebilir üretim","body":"Maketin sergileneceği alan ve taşınacağı kutu boyutu, parçalara ayırma kararını etkiler. Birleşim yerlerini görünür cephelerden uzaklaştırmak veya sökülebilir kütleler kullanmak tasarım aşamasında değerlendirilebilir. Aydınlatma ve kablo kanalları ayrıca belirtilmelidir."},{"title":"Sunum onayı","body":"Renk, yüzey, etiket ve taban beklentisini referanslarla anlatın. Önce dijital yerleşim, sonra kritik bir detayın numunesi üzerinden karar verin. Son teslimden önce parça listesi ve yerleşim şemasını birlikte kontrol edin."}]'::jsonb,'sector','/brand/industrial/parts.webp','[{"q":"İlk değerlendirme için ne paylaşmalıyım?","a":"Kaynak modelin birimini, hedef maket ölçeğini ve bitmiş taban ölçüsünü paylaşın. Cephedeki çok küçük detayların fiziksel makette nasıl temsil edileceğini kararlaştırın. Peyzaj, kütle ve iç mekân farklı ayrıntı seviyelerinde ele alınabilir."},{"q":"Talebe nasıl başlayabilirim?","a":"3D Studio üzerinden dosyanızı, adet ve kullanım koşullarınızı paylaşabilirsiniz. Dosyanız yoksa fotoğraf, ölçü ve beklenen çıktıyla modelleme değerlendirmesi isteyin."}]'::jsonb,'published','','','','','','','',NULL FROM public.tenants WHERE slug='parcayanimda' ON CONFLICT(tenant_id,path) DO NOTHING;
INSERT INTO public.landing_pages(tenant_id,path,title,summary,sections,kind,image,faq,status,city,district,neighborhood,service,local_context,logistics,evidence,reviewed_at) SELECT id,'/sektorler/medikal','Medikal tasarım ve eğitim','Anlatım, eğitim ve tasarım değerlendirmesi için anatomik gösterim ve cihaz gövdesi prototiplerinin kapsamını belirleyin. parçayanımda: özel plastik parça & otomotiv odağında değerlendirme.','[{"title":"Özel plastik parça & otomotiv","body":"parçayanımda: İstanbul’da 3D baskı, 3D tarama ve 3D modelleme. Özel plastik parça & otomotiv için proje bazlı üretim. Projenizde 3D baskı, 3D tarama ve 3D modelleme adımlarından hangilerinin gerekli olduğunu kullanım amacınızla birlikte belirleyin."},{"title":"Kullanım amacını ayırın","body":"Eğitimde gösterim, cihazın form kontrolü ve klinik kullanım birbirinden farklı kapsamlar taşır. Talebinizin hangi amaçla kullanılacağını açıkça yazın. Bu sayfadaki prototipleme yaklaşımı klinik uygunluk, sterilizasyon veya hasta temasına ilişkin bir onay değildir."},{"title":"Veri paylaşımı","body":"Gerekli dosya formatını ve görüntüleme beklentisini teknik ekiple belirleyin. Kişisel bilgi içeren görüntü veya dosyaları paylaşmadan önce yetki ve anonimleştirme süreçlerinizi tamamlayın. Teklif aşamasında mümkünse kimlik bilgisi içermeyen geometriyle başlayın."},{"title":"Eğitim modelinin kabulü","body":"Gösterilecek yapıları, renk ayrımını, sökülebilir bölümleri ve kullanılacak ölçeği listeleyin. Modelin anlatım amacına uygunluğunu konu uzmanı değerlendirmelidir. Dijital onay ile fiziksel yüzey beklentisini ayrı adımlarda ele alın."}]'::jsonb,'sector','/brand/industrial/parts.webp','[{"q":"İlk değerlendirme için ne paylaşmalıyım?","a":"Eğitimde gösterim, cihazın form kontrolü ve klinik kullanım birbirinden farklı kapsamlar taşır. Talebinizin hangi amaçla kullanılacağını açıkça yazın. Bu sayfadaki prototipleme yaklaşımı klinik uygunluk, sterilizasyon veya hasta temasına ilişkin bir onay değildir."},{"q":"Talebe nasıl başlayabilirim?","a":"3D Studio üzerinden dosyanızı, adet ve kullanım koşullarınızı paylaşabilirsiniz. Dosyanız yoksa fotoğraf, ölçü ve beklenen çıktıyla modelleme değerlendirmesi isteyin."}]'::jsonb,'published','','','','','','','',NULL FROM public.tenants WHERE slug='parcayanimda' ON CONFLICT(tenant_id,path) DO NOTHING;
INSERT INTO public.landing_pages(tenant_id,path,title,summary,sections,kind,image,faq,status,city,district,neighborhood,service,local_context,logistics,evidence,reviewed_at) SELECT id,'/sektorler/savunma-havacilik','Havacılık ve teknik Ar-Ge','Form kontrolü, ergonomi ve montaj gösterimi için kullanılan teknik prototipleri izlenebilir bir dosya akışıyla planlayın. parçayanımda: özel plastik parça & otomotiv odağında değerlendirme.','[{"title":"Özel plastik parça & otomotiv","body":"parçayanımda: İstanbul’da 3D baskı, 3D tarama ve 3D modelleme. Özel plastik parça & otomotiv için proje bazlı üretim. Projenizde 3D baskı, 3D tarama ve 3D modelleme adımlarından hangilerinin gerekli olduğunu kullanım amacınızla birlikte belirleyin."},{"title":"Kapsam ve veri sınırı","body":"Paylaşıma yetkili olduğunuz çizimleri ve kullanım amacı bilgisini talebe ekleyin. İlk değerlendirme için gerekli olmayan hassas proje detaylarını kapsam dışında tutun. Dosya erişimi, gizlilik ve revizyon sorumluları teklif öncesinde belirlenmelidir."},{"title":"Gösterim ve montaj prototipi","body":"Ergonomi maketi, bağlantı yerleşimi veya dış form numunesinde hangi kararın doğrulanacağını yazın. Görsel prototipin uçuşa elverişlilik veya işlevsel parça sertifikası sağlamadığını proje içinde açıkça ayırın. Kritik işlevler ayrı doğrulama planı gerektirir."},{"title":"İzlenebilir değerlendirme","body":"Dosya adı, parça kodu, revizyon, talep sahibi ve kabul kontrolünü ortak tabloda tutun. Fiziksel numune üzerindeki değişiklikleri dijital modele geri işleyin. Tekrar üretimde onaylı dosyanın aynı olduğundan emin olun."}]'::jsonb,'sector','/brand/industrial/parts.webp','[{"q":"İlk değerlendirme için ne paylaşmalıyım?","a":"Paylaşıma yetkili olduğunuz çizimleri ve kullanım amacı bilgisini talebe ekleyin. İlk değerlendirme için gerekli olmayan hassas proje detaylarını kapsam dışında tutun. Dosya erişimi, gizlilik ve revizyon sorumluları teklif öncesinde belirlenmelidir."},{"q":"Talebe nasıl başlayabilirim?","a":"3D Studio üzerinden dosyanızı, adet ve kullanım koşullarınızı paylaşabilirsiniz. Dosyanız yoksa fotoğraf, ölçü ve beklenen çıktıyla modelleme değerlendirmesi isteyin."}]'::jsonb,'published','','','','','','','',NULL FROM public.tenants WHERE slug='parcayanimda' ON CONFLICT(tenant_id,path) DO NOTHING;
INSERT INTO public.landing_pages(tenant_id,path,title,summary,sections,kind,image,faq,status,city,district,neighborhood,service,local_context,logistics,evidence,reviewed_at) SELECT id,'/sektorler/egitim-arge','Eğitim ve Ar-Ge','Fikrinizi test edilebilir numunelere ayırın; bir sonraki tasarım kararını verecek prototipi üretin. parçayanımda: özel plastik parça & otomotiv odağında değerlendirme.','[{"title":"Özel plastik parça & otomotiv","body":"parçayanımda: İstanbul’da 3D baskı, 3D tarama ve 3D modelleme. Özel plastik parça & otomotiv için proje bazlı üretim. Projenizde 3D baskı, 3D tarama ve 3D modelleme adımlarından hangilerinin gerekli olduğunu kullanım amacınızla birlikte belirleyin."},{"title":"Deneyi önce tanımlayın","body":"Bu numuneyle hangi soruya yanıt aradığınızı yazın. Form, mekanizma hareketi ve montaj uyumu farklı deneylerdir. Her birini aynı prototipte çözmeye çalışmak yerine karar sırasına göre ayırın."},{"title":"Revizyonları karşılaştırın","body":"Alternatifleri dosya adında işaretleyin; yalnızca değişen parametreleri bir tabloyla paylaşın. Deneme sonucunu not ederken kullanılan revizyonu ve test koşullarını ekleyin. Böylece yeni numunenin neden istendiği açık kalır."},{"title":"Bütçe ve adet","body":"Görünüş değerlendirmesi için gereken adetle kullanıcı testi için gereken adet aynı olmayabilir. Önce küçük bir doğrulama grubu planlayın. Malzeme, yüzey ve teslim tarihi seçimlerini deneyin amacıyla birlikte değerlendirin."}]'::jsonb,'sector','/brand/industrial/parts.webp','[{"q":"İlk değerlendirme için ne paylaşmalıyım?","a":"Bu numuneyle hangi soruya yanıt aradığınızı yazın. Form, mekanizma hareketi ve montaj uyumu farklı deneylerdir. Her birini aynı prototipte çözmeye çalışmak yerine karar sırasına göre ayırın."},{"q":"Talebe nasıl başlayabilirim?","a":"3D Studio üzerinden dosyanızı, adet ve kullanım koşullarınızı paylaşabilirsiniz. Dosyanız yoksa fotoğraf, ölçü ve beklenen çıktıyla modelleme değerlendirmesi isteyin."}]'::jsonb,'published','','','','','','','',NULL FROM public.tenants WHERE slug='parcayanimda' ON CONFLICT(tenant_id,path) DO NOTHING;
INSERT INTO public.landing_pages(tenant_id,path,title,summary,sections,kind,image,faq,status,city,district,neighborhood,service,local_context,logistics,evidence,reviewed_at) SELECT id,'/sektorler/sanat-mucevher','Sanat, obje ve takı tasarımı','Heykel, obje ve takı tasarımlarında dijital formu fiziksel ölçekte görerek yüzey ve detay kararlarını geliştirin. parçayanımda: özel plastik parça & otomotiv odağında değerlendirme.','[{"title":"Özel plastik parça & otomotiv","body":"parçayanımda: İstanbul’da 3D baskı, 3D tarama ve 3D modelleme. Özel plastik parça & otomotiv için proje bazlı üretim. Projenizde 3D baskı, 3D tarama ve 3D modelleme adımlarından hangilerinin gerekli olduğunu kullanım amacınızla birlikte belirleyin."},{"title":"Formun fiziksel etkisi","body":"Ekranda büyük görünen bir detay gerçek ölçekte kaybolabilir. Hedef ölçüyü, tutulacak yüzeyleri ve sergileme yönünü paylaşın. Organik modellerde yüzey sürekliliği ile bilinçli doku kararlarını ayırın."},{"title":"Son işlem planı","body":"Boyama, birleştirme veya başka bir üretim sürecine girdi oluşturma amacı varsa bunu baştan belirtin. Kalıp veya döküm sürecine uygunluk ilgili üretim yöntemiyle ayrıca değerlendirilmelidir. Her baskı malzemesinin her son işlemle uyumlu olduğu varsayılmaz."},{"title":"Tasarım hakları","body":"Üretim için ilettiğiniz modelin kullanım hakkının sizde olduğundan emin olun. Sanatçı adı, eser numarası ve revizyonu dosyada takip edin. Görsel sunum numunesi ile satışa çıkacak nihai ürünün kabul ölçütlerini ayrı belirleyin."}]'::jsonb,'sector','/brand/industrial/parts.webp','[{"q":"İlk değerlendirme için ne paylaşmalıyım?","a":"Ekranda büyük görünen bir detay gerçek ölçekte kaybolabilir. Hedef ölçüyü, tutulacak yüzeyleri ve sergileme yönünü paylaşın. Organik modellerde yüzey sürekliliği ile bilinçli doku kararlarını ayırın."},{"q":"Talebe nasıl başlayabilirim?","a":"3D Studio üzerinden dosyanızı, adet ve kullanım koşullarınızı paylaşabilirsiniz. Dosyanız yoksa fotoğraf, ölçü ve beklenen çıktıyla modelleme değerlendirmesi isteyin."}]'::jsonb,'published','','','','','','','',NULL FROM public.tenants WHERE slug='parcayanimda' ON CONFLICT(tenant_id,path) DO NOTHING;
INSERT INTO public.landing_pages(tenant_id,path,title,summary,sections,kind,image,faq,status,city,district,neighborhood,service,local_context,logistics,evidence,reviewed_at) SELECT id,'/sektorler/drone-hobi','Drone, robotik ve hobi','Elektronik yerleşimi, kablo yönetimi ve montaj yardımcıları için modelleme ve prototip planınızı oluşturun. parçayanımda: özel plastik parça & otomotiv odağında değerlendirme.','[{"title":"Özel plastik parça & otomotiv","body":"parçayanımda: İstanbul’da 3D baskı, 3D tarama ve 3D modelleme. Özel plastik parça & otomotiv için proje bazlı üretim. Projenizde 3D baskı, 3D tarama ve 3D modelleme adımlarından hangilerinin gerekli olduğunu kullanım amacınızla birlikte belirleyin."},{"title":"Bileşen yerleşimi","body":"Kart, sensör, bağlantı ve kablo ölçülerini aynı referans sisteminde paylaşın. Montaj sırasında alet erişimi ve kablo bükülme alanını da düşünün. Sadece dış ölçüleri vermek, parçanın sorunsuz monte edileceğini göstermez."},{"title":"Deneme koşulları","body":"Titreşim, dış ortam ve hareketli mekanizma ilişkisini belirtin. Uçuş veya yüksek hız gerektiren kullanımda parça doğrulaması ayrıca ele alınmalıdır. Tasarım numunesini doğrudan güvenlik açısından kritik kullanıma uygun kabul etmeyin."},{"title":"Onarım ve değiştirme","body":"Sık sökülecek kapakları, tüketilecek parçaları ve farklı sürümlerde değişecek bağlantıları işaretleyin. Tasarımın servis kolaylığı prototip üzerinden kontrol edilebilir. Sonraki sipariş için onaylanan dosyayı ve bağlantı ölçülerini saklayın."}]'::jsonb,'sector','/brand/industrial/parts.webp','[{"q":"İlk değerlendirme için ne paylaşmalıyım?","a":"Kart, sensör, bağlantı ve kablo ölçülerini aynı referans sisteminde paylaşın. Montaj sırasında alet erişimi ve kablo bükülme alanını da düşünün. Sadece dış ölçüleri vermek, parçanın sorunsuz monte edileceğini göstermez."},{"q":"Talebe nasıl başlayabilirim?","a":"3D Studio üzerinden dosyanızı, adet ve kullanım koşullarınızı paylaşabilirsiniz. Dosyanız yoksa fotoğraf, ölçü ve beklenen çıktıyla modelleme değerlendirmesi isteyin."}]'::jsonb,'published','','','','','','','',NULL FROM public.tenants WHERE slug='parcayanimda' ON CONFLICT(tenant_id,path) DO NOTHING;
INSERT INTO public.landing_pages(tenant_id,path,title,summary,sections,kind,image,faq,status,city,district,neighborhood,service,local_context,logistics,evidence,reviewed_at) SELECT id,'/rehber/stl-dosya-hazirlama','STL dosyası hazırlama kontrol listesi','Tekliften önce birim, dış ölçü, yüzey bütünlüğü ve revizyon bilgisini aynı kontrol listesiyle gözden geçirin. parçayanımda: özel plastik parça & otomotiv odağında değerlendirme.','[{"title":"Özel plastik parça & otomotiv","body":"parçayanımda: İstanbul’da 3D baskı, 3D tarama ve 3D modelleme. Özel plastik parça & otomotiv için proje bazlı üretim. Projenizde 3D baskı, 3D tarama ve 3D modelleme adımlarından hangilerinin gerekli olduğunu kullanım amacınızla birlikte belirleyin."},{"title":"Birim ve ölçek","body":"STL dosyasındaki koordinatları hangi birimde dışa aktardığınızı kaydedin. Önizleyicide dış ölçüleri tasarımınızla karşılaştırın. Milimetre ve inç karışıklığı, görünüş aynı olsa da üretilecek parçanın boyutunu değiştirir."},{"title":"Yüzey ve ayrıntı","body":"Modelde açık yüzey, üst üste geometri veya istenmeyen iç parçalar olup olmadığını CAD yazılımınızda kontrol edin. Görüntüleyicide kesit almak iç ilişkileri anlamayı kolaylaştırır; ancak otomatik üretilebilirlik doğrulamasının yerini tutmaz."},{"title":"Dosya paketi","body":"Parça kodu ve revizyonu dosya adına ekleyin. Adet, kritik ölçü ve kullanım koşullarını ayrı not edin. Birden fazla dosyada aynı kodu farklı revizyonlarla karıştırmayın; onaylanmış sürümü açıkça işaretleyin."}]'::jsonb,'guide','/brand/industrial/parts.webp','[{"q":"İlk değerlendirme için ne paylaşmalıyım?","a":"STL dosyasındaki koordinatları hangi birimde dışa aktardığınızı kaydedin. Önizleyicide dış ölçüleri tasarımınızla karşılaştırın. Milimetre ve inç karışıklığı, görünüş aynı olsa da üretilecek parçanın boyutunu değiştirir."},{"q":"Talebe nasıl başlayabilirim?","a":"3D Studio üzerinden dosyanızı, adet ve kullanım koşullarınızı paylaşabilirsiniz. Dosyanız yoksa fotoğraf, ölçü ve beklenen çıktıyla modelleme değerlendirmesi isteyin."}]'::jsonb,'published','','','','','','','',NULL FROM public.tenants WHERE slug='parcayanimda' ON CONFLICT(tenant_id,path) DO NOTHING;
INSERT INTO public.landing_pages(tenant_id,path,title,summary,sections,kind,image,faq,status,city,district,neighborhood,service,local_context,logistics,evidence,reviewed_at) SELECT id,'/rehber/tarama-verisinden-cad','Tarama verisinden CAD modeline','Nokta bulutu, yüzey ağı ve düzenlenebilir CAD çıktısını ayırarak tersine mühendislik talebinizi doğru kapsamlandırın. parçayanımda: özel plastik parça & otomotiv odağında değerlendirme.','[{"title":"Özel plastik parça & otomotiv","body":"parçayanımda: İstanbul’da 3D baskı, 3D tarama ve 3D modelleme. Özel plastik parça & otomotiv için proje bazlı üretim. Projenizde 3D baskı, 3D tarama ve 3D modelleme adımlarından hangilerinin gerekli olduğunu kullanım amacınızla birlikte belirleyin."},{"title":"Hangi veri elinizde?","body":"Tarama sonucunuz nokta verisi veya üçgen yüzey ağı olabilir. Düzenlenebilir katı model gereksinimini ayrıca belirtin. Görüntülenebilen bir dosyanın otomatik olarak parametrik CAD dosyası olduğu varsayılmaz."},{"title":"Fonksiyonel yüzeyler","body":"Delik, mil yatağı, oturma yüzeyi ve bağlantı eksenlerini işaretleyin. Aşınmış veya kırılmış bölgeyi olduğu gibi kopyalamak yerine korunması gereken tasarım ilişkisini açıklayın. Gerekirse sağlam karşı parça da değerlendirmeye eklenir."},{"title":"Teslim ve kontrol","body":"İstenen formatı, revizyon kapsamını ve kontrol edilecek ölçüleri baştan belirleyin. Tarama ile CAD arasındaki farkların nasıl değerlendirileceğini kararlaştırın. Sadece görsel benzerlik, ölçüsel kabulün yerine geçmez."}]'::jsonb,'guide','/brand/industrial/parts.webp','[{"q":"İlk değerlendirme için ne paylaşmalıyım?","a":"Tarama sonucunuz nokta verisi veya üçgen yüzey ağı olabilir. Düzenlenebilir katı model gereksinimini ayrıca belirtin. Görüntülenebilen bir dosyanın otomatik olarak parametrik CAD dosyası olduğu varsayılmaz."},{"q":"Talebe nasıl başlayabilirim?","a":"3D Studio üzerinden dosyanızı, adet ve kullanım koşullarınızı paylaşabilirsiniz. Dosyanız yoksa fotoğraf, ölçü ve beklenen çıktıyla modelleme değerlendirmesi isteyin."}]'::jsonb,'published','','','','','','','',NULL FROM public.tenants WHERE slug='parcayanimda' ON CONFLICT(tenant_id,path) DO NOTHING;
